import { app, BrowserWindow, ipcMain, dialog, shell, clipboard, nativeImage, session as electronSession } from 'electron';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import fs from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { z } from 'zod';
import { Store, settingsSchema } from './core/store';
import { Jobs } from './core/jobs';
import { Auth } from './core/auth';
import { Minecraft } from './core/minecraft';
import { Modrinth } from './core/modrinth';
import { Sakura } from './core/sakura';
import { Social, friendsUrl } from './core/social';
import { Rooms } from './core/rooms';
import { identifier, leafSchema, portSchema, safeMessage, under } from './core/safety';
import { decodeInvite } from './core/invite';
import { exists } from './core/files';
import { scanLocalFolder } from './core/local-scan';
import { copyLocalContent, canRepairImported } from './core/local-import';
import { atomicWrite } from './core/files';
import { storageRoot, prepareStorage, migrateStorage, type StoragePlan } from './core/storage';
import type { CommandMap, LocalScan } from '../shared/types';
const idInput = z.object({ id: identifier });
const externalHosts = ['modrinth.com', 'www.natfrp.com', 'natfrp.com', 'doc.natfrp.com', 'www.minecraft.net', 'minecraft.net', 'login.microsoftonline.com', 'www.microsoft.com', 'microsoft.com', 'microsoft.com', 'aka.ms', 'learn.microsoft.com'];
let mainWindow: BrowserWindow | undefined;
let portalWindow: BrowserWindow | undefined;
if (process.env.QINGLAN_DATA_DIR) app.setPath('userData', path.resolve(process.env.QINGLAN_DATA_DIR));
if (!app.requestSingleInstanceLock()) app.quit();
else {
  app.on('second-instance', () => { mainWindow?.show(); mainWindow?.focus(); });
  void app.whenReady().then(start).catch(error => { dialog.showErrorBox('OLS 启动器无法启动', safeMessage(error)); app.quit(); });
}
async function start() {
  const storagePointer=path.join(app.getPath('userData'),'storage.json');
  const store = new Store(await storageRoot(app.getPath('userData'))); await store.init();
  const jobs = new Jobs(store); const auth = new Auth(store); const minecraft = new Minecraft(store, auth);
  const mods = new Modrinth(store); const sakura = new Sakura(store); const social = new Social(store);
  const bundled = app.isPackaged ? path.join(process.resourcesPath, 'bundled') : path.join(app.getAppPath(), 'resources');
  const rooms = new Rooms(store, minecraft, mods, sakura, social, bundled);
  const localScans = new Map<string, LocalScan>();
  let scanningLocal = false;
  let storagePlan:StoragePlan|undefined;let migrating=false;
  const requireIdle=()=>{if(store.state.running.length||!['idle','error'].includes(store.state.room.state)||store.state.jobs.some(job=>['queued','running'].includes(job.status))||scanningLocal)throw new Error('请退出游戏、关闭联机并等待文件任务完成后迁移');};
  mainWindow = new BrowserWindow({ width: 1380, height: 900, minWidth: 1000, minHeight: 700, title: 'OLS 启动器', frame: false, backgroundColor: '#f4f7f6', show: false,
    webPreferences: { preload: path.join(__dirname, 'preload.cjs'), contextIsolation: true, nodeIntegration: false, sandbox: true, webSecurity: true, spellcheck: false } });
  mainWindow.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));
  mainWindow.webContents.on('will-navigate', event => event.preventDefault());
  mainWindow.webContents.session.setPermissionRequestHandler((_contents, _permission, callback) => callback(false));
  let notification: NodeJS.Timeout | undefined;
  store.onChange = () => {
    if (notification) return;
    notification = setTimeout(() => { notification = undefined; if (mainWindow && !mainWindow.isDestroyed()) mainWindow.webContents.send('qinglan:state', store.state); }, 250);
  };
  async function openPortal(page: 'account' | 'checkin' | 'tunnels') {
    if (portalWindow && !portalWindow.isDestroyed()) { portalWindow.focus(); return; }
    portalWindow = new BrowserWindow({ width: 1080, height: 790, parent: mainWindow, autoHideMenuBar: true, title: page === 'checkin' ? '樱花穿透 · 官方签到（验证由你完成）' : '樱花穿透 · 官方账户管理', webPreferences: { contextIsolation: true, nodeIntegration: false, sandbox: true, partition: 'persist:sakura-official' } });
    portalWindow.webContents.session.setPermissionRequestHandler((_c, _p, cb) => cb(false));
    portalWindow.webContents.on('will-navigate', (event, url) => { if (!url.startsWith('https://')) event.preventDefault(); });
    portalWindow.webContents.setWindowOpenHandler(({ url }) => { if (url.startsWith('https://')) void shell.openExternal(url); return { action: 'deny' }; });
    const closed = new Promise<void>(resolve => portalWindow!.once('closed', () => { portalWindow = undefined; resolve(); }));
    await portalWindow.loadURL(page === 'tunnels' ? 'https://www.natfrp.com/tunnel/' : 'https://www.natfrp.com/user/');
    await closed;
  }
  async function command(command: keyof CommandMap, raw: unknown): Promise<unknown> {
    if(migrating&&!['state','getBackground','window','cancelJob'].includes(command))throw new Error('正在迁移存储位置，请等待完成或在下载管理取消任务');
    switch (command) {
      case 'chooseStorage': {
        requireIdle();const result=await dialog.showOpenDialog(mainWindow!,{properties:['openDirectory','createDirectory'],title:'选择存储位置（将在该目录下创建 OLSData）'});
        if(result.canceled||!result.filePaths[0])return null;
        requireIdle();await store.save();storagePlan=await prepareStorage(store.root,path.join(await fs.realpath(result.filePaths[0]),'OLSData'));return storagePlan;
      }
      case 'migrateStorage': {
        const input=z.object({planId:z.string().uuid()}).parse(raw);requireIdle();
        const plan=storagePlan;if(!plan||plan.id!==input.planId||Date.now()-plan.createdAt>600000)throw new Error('迁移预览已过期，请重新选择位置');storagePlan=undefined;
        migrating=true;auth.cancel();
        return jobs.add('迁移本地存储位置',async context=>{try{
          await social.pause();await store.flush();
          await migrateStorage(plan,context,async target=>{
            // A manually selected Java executable inside OLS data follows the copy.
            const javaPath=store.state.settings.javaPath;const relJava=javaPath?path.relative(plan.source,javaPath):undefined;
            const remappedJava=relJava&&!relJava.startsWith(`..${path.sep}`)&&relJava!=='..'&&!path.isAbsolute(relJava)?path.join(target,relJava):javaPath;
            if(remappedJava!==javaPath){const saved=JSON.parse(await fs.readFile(path.join(target,'state.json'),'utf8'));saved.settings.javaPath=remappedJava;await atomicWrite(path.join(target,'state.json'),JSON.stringify(saved,null,2));}
            await atomicWrite(storagePointer,JSON.stringify({schema:1,root:target},null,2));
            store.root=target;store.state.settings={...store.state.settings,javaPath:remappedJava};store.state.dataDir=target;store.changed();
          });
        }finally{migrating=false;social.start();}});
      }
      case 'state': return store.state;
      case 'versions': return minecraft.versions();
      case 'scanLocal': {
        if (scanningLocal) throw new Error('正在识别本地游戏，请稍候');
        scanningLocal = true;
        try {
          const result = await dialog.showOpenDialog(mainWindow!, { title: '选择游戏目录、.minecraft、具体版本目录或整合包实例', properties: ['openDirectory'] });
          if (result.canceled || !result.filePaths[0]) return null;
          const scan = await scanLocalFolder(result.filePaths[0]);
          localScans.set(scan.id, scan);
          while (localScans.size > 5) localScans.delete(localScans.keys().next().value!);
          return scan;
        } finally { scanningLocal = false; }
      }
      case 'importLocal': {
        const input = z.object({ scanId: z.string().uuid(), profileId: z.string().uuid() }).parse(raw);
        const scan = localScans.get(input.scanId);
        if (!scan || Date.now() - Date.parse(scan.scannedAt) > 30 * 60000) throw new Error('扫描结果已过期，请重新选择游戏文件夹');
        const profile = scan.profiles.find(profile => profile.id === input.profileId);
        if (!profile?.canImport || !profile.gameVersion || !['vanilla', 'fabric'].includes(profile.loader)) throw new Error(profile?.importReason || '这个版本暂不支持导入');
        const source = profile.versionDir || profile.gameDir;
        const existing = store.state.instances.find(instance => instance.importedFrom === source);
        if (existing && existing.importState !== 'failed') throw new Error('这个本地版本已经添加到游戏库，可在那里查看或在下载管理继续导入');
        const instance = existing || { ...minecraft.newInstance(profile.name.slice(0, 60), profile.gameVersion, profile.loader === 'fabric' ? 'fabric' : 'vanilla', profile.loaderVersion), importedFrom: source, importState: 'copying' as const };
        if (!existing) store.state.instances.push(instance);
        instance.importCache = { cacheRoot: profile.cacheRoot, versionDir: profile.versionDir };
        store.state.selectedId = instance.id; await store.save();
        return jobs.add(`导入本地游戏 · ${instance.name}`, async context => {
          instance.importState = 'copying'; instance.installed = false; await store.save();
          try {
            const resources = await copyLocalContent(profile, store.instanceDir(instance.id), context);
            instance.resources = resources; instance.importState = 'copied'; await store.save();
            await minecraft.install(instance, context, { cacheRoot: profile.cacheRoot, versionDir: profile.versionDir });
            store.log(`${instance.name} 本地游戏导入完成：${resources.length} 个资源`);
          } catch (error) {
            if (instance.importState === 'copying') instance.importState = 'failed';
            await store.save(); throw error;
          }
        });
      }
      case 'install': {
        const input = z.object({ name: z.string().trim().min(1).max(60), gameVersion: identifier, loader: z.enum(['vanilla', 'fabric']), loaderVersion: identifier.optional() }).parse(raw);
        const instance = minecraft.newInstance(input.name, input.gameVersion, input.loader, input.loaderVersion);
        store.state.instances.push(instance); store.state.selectedId = instance.id; await store.save();
        return jobs.add(`安装 ${instance.name}`, context => minecraft.install(instance, context));
      }
      case 'select': { const { id } = idInput.parse(raw); store.instance(id); store.state.selectedId = id; await store.save(); return; }
      case 'launch': { const { id } = idInput.parse(raw); return jobs.add(`启动 ${store.instance(id).name}`, context => minecraft.launch(id, context)); }
      case 'repair': { const { id } = idInput.parse(raw); if (store.state.running.includes(id)) throw new Error('请先退出游戏'); canRepairImported(store.instance(id)); return jobs.add(`校验与修复 ${store.instance(id).name}`, context => minecraft.install(store.instance(id), context)); }
      case 'worlds': return minecraft.worlds(idInput.parse(raw).id);
      case 'importWorld': {
        const { id } = idInput.parse(raw); store.instance(id); if (store.state.running.includes(id)) throw new Error('请先退出游戏再导入世界');
        const result = await dialog.showOpenDialog(mainWindow!, { title: '选择包含 level.dat 的存档文件夹（请先关闭原游戏）', properties: ['openDirectory'] });
        if (result.canceled || !result.filePaths[0]) return null;
        const source = result.filePaths[0]; if (!await exists(path.join(source, 'level.dat'))) throw new Error('此文件夹没有 level.dat，不是有效的世界存档');
        const folder = leafSchema.parse(path.basename(source)); const destination = under(store.instanceDir(id), 'saves', folder);
        if (await exists(destination)) throw new Error('同名世界已存在，请先在源文件夹改名');
        const check = async (dir: string): Promise<void> => { for (const item of await fs.readdir(dir, { withFileTypes: true })) { if (item.isSymbolicLink()) throw new Error('导入的世界不能包含符号链接'); if (item.isDirectory()) await check(path.join(dir, item.name)); } };
        await check(source); await fs.cp(source, destination, { recursive: true, errorOnExist: true, force: false }); return folder;
      }
      case 'search': return mods.search(z.object({ query: z.string().max(200), kind: z.enum(['mod', 'shader', 'resourcepack']), instanceId: identifier.optional(), offset: z.number().int().min(0).max(100000).optional(), sort: z.enum(['downloads', 'relevance', 'updated']).optional() }).parse(raw));
      case 'installResource': {
        const input = z.object({ instanceId: identifier, projectId: identifier, kind: z.enum(['mod', 'shader', 'resourcepack']) }).parse(raw);
        return jobs.add('安装资源与依赖', context => mods.install(store.instance(input.instanceId), input.projectId, input.kind, context));
      }
      case 'toggleResource': { const input = z.object({ instanceId: identifier, projectId: identifier }).parse(raw); return mods.toggle(input.instanceId, input.projectId); }
      case 'saveSettings': {
        const input = settingsSchema.parse(raw); friendsUrl(input.friendsServer);
        if (input.friendsServer !== store.state.settings.friendsServer) { await rooms.stop(); await social.logout(); }
        store.state.settings = { ...input, backgroundRevision: store.state.settings.backgroundRevision }; await store.save(); mainWindow?.setBackgroundColor(input.theme === 'dark' ? '#111b1b' : '#f4f7f6'); return;
      }
      case 'chooseBackground': {
        const result = await dialog.showOpenDialog(mainWindow!, { properties: ['openFile'], title: '选择背景图片', filters: [{ name: '背景图片', extensions: ['png', 'jpg', 'jpeg', 'webp'] }] });
        if (result.canceled || !result.filePaths[0]) return false;
        const source = result.filePaths[0]; const stat = await fs.stat(source);
        if (!stat.isFile() || stat.size > 24 * 1024 * 1024) throw new Error('请选择小于 24 MB 的图片');
        let image = nativeImage.createFromBuffer(await fs.readFile(source));
        const size = image.getSize();
        if (image.isEmpty() || size.width > 16384 || size.height > 16384) throw new Error('图片无效或尺寸过大，请使用 PNG、JPEG 或 WebP 静态图片');
        const ratio = Math.min(1, 2560 / Math.max(size.width, size.height));
        if (ratio < 1) image = image.resize({ width: Math.max(1, Math.round(size.width * ratio)), height: Math.max(1, Math.round(size.height * ratio)) });
        await atomicWrite(store.file('appearance', 'background.png'), image.toPNG());
        store.state.settings.backgroundRevision = randomUUID(); await store.save(); return true;
      }
      case 'getBackground': {
        if (!store.state.settings.backgroundRevision) return null;
        try { return `data:image/png;base64,${(await fs.readFile(store.file('appearance', 'background.png'))).toString('base64')}`; } catch { return null; }
      }
      case 'resetBackground': {
        await fs.rm(store.file('appearance', 'background.png'), { force: true });
        store.state.settings.backgroundRevision = undefined; await store.save(); return;
      }
      case 'chooseJava': { const result = await dialog.showOpenDialog(mainWindow!, { properties: ['openFile'], title: '选择 java.exe', filters: [{ name: 'Java 运行程序', extensions: ['exe'] }] }); return result.canceled ? null : result.filePaths[0]; }
      case 'login': return auth.login();
      case 'cancelLogin': return auth.cancel();
      case 'logout': return auth.logout();
      case 'saveSakura': return sakura.saveToken(z.object({ token: z.string().trim().min(8).max(512).regex(/^[a-zA-Z0-9_-]+$/) }).parse(raw).token);
      case 'sakuraNodes': return sakura.nodes();
      case 'sakuraTunnels': return sakura.tunnels();
      case 'sakuraAccount': return sakura.account();
      case 'sakuraPortal': return openPortal(z.object({ page: z.enum(['account', 'checkin', 'tunnels']) }).parse(raw).page);
      case 'sakuraLogout': await rooms.stop(); await sakura.logout(); await electronSession.fromPartition('persist:sakura-official').clearStorageData(); return;
      case 'deleteTunnel': return sakura.delete(z.object({ id: z.number().int().positive() }).parse(raw).id);
      case 'host': { const input = z.object({ instanceId: identifier, world: leafSchema.optional(), nodeId: z.number().int().positive(), localPort: portSchema, mode: z.enum(['auto', 'manual']), tunnelId: z.number().int().positive().optional() }).parse(raw); return jobs.add('向好友开放世界', context => rooms.host(input, context)); }
      case 'stopRoom': return rooms.stop();
      case 'decodeInvite': return decodeInvite(z.object({ code: z.string().max(24000) }).parse(raw).code);
      case 'join': { const descriptor = decodeInvite(z.object({ code: z.string().max(24000) }).parse(raw).code); return jobs.add('准备好友游戏环境', context => rooms.join(descriptor, context)); }
      case 'socialLogin': return social.login(z.object({ username: z.string().max(24), password: z.string().min(10).max(128), nickname: z.string().max(30).optional(), register: z.boolean() }).parse(raw));
      case 'socialLogout': await rooms.stop(); return social.logout();
      case 'addFriend': return social.add(z.object({ username: z.string().max(24) }).parse(raw).username);
      case 'respondFriend': { const input = z.object({ id: z.string().uuid(), accept: z.boolean() }).parse(raw); return social.respond(input.id, input.accept); }
      case 'removeFriend': return social.remove(z.object({ id: z.string().uuid() }).parse(raw).id);
      case 'friendRoom': return social.getRoom(z.object({id:z.string().uuid()}).parse(raw).id);
      case 'checkFriendMods': {const input=z.object({id:z.string().uuid(),instanceId:identifier}).parse(raw);return rooms.checkLocal(await social.getRoom(input.id),input.instanceId);}
      case 'joinFriend': { const input = z.object({ id: z.string().uuid(), instanceId:identifier.optional() }).parse(raw); return jobs.add('加入好友的世界', async context => rooms.join(await social.getRoom(input.id), context,input.instanceId)); }
      case 'cancelJob': return jobs.cancel(idInput.parse(raw).id);
      case 'retryJob': { const {id}=idInput.parse(raw);if(store.state.jobs.find(job=>job.id===id)?.title==='迁移本地存储位置')throw new Error('迁移失败或取消后，请重新选择空目录并预览后开始，不能直接重放旧迁移任务');return jobs.retry(id); }
      case 'openFolder': {
        const input = z.object({ id: identifier.optional(), kind: z.enum(['instance', 'mods', 'shaderpacks', 'resourcepacks', 'logs']).optional() }).parse(raw);
        let directory = store.root;
        if (input.id) { store.instance(input.id); directory = store.instanceDir(input.id); }
        if (input.kind && input.kind !== 'instance') directory = under(directory, input.kind);
        await fs.mkdir(directory, { recursive: true }); const error = await shell.openPath(directory); if (error) throw new Error(error); return;
      }
      case 'openExternal': { const { url } = z.object({ url: z.string().url().max(1000) }).parse(raw); const parsed = new URL(url); if (parsed.protocol !== 'https:' || parsed.username || parsed.password || !externalHosts.includes(parsed.hostname)) throw new Error('此链接不在支持的官方站点中'); await shell.openExternal(url); return; }
      case 'copy': clipboard.writeText(z.object({ text: z.string().max(24000) }).parse(raw).text); return;
      case 'window': { const { action } = z.object({ action: z.enum(['minimize', 'maximize', 'close']) }).parse(raw); if (action === 'minimize') mainWindow?.minimize(); else if (action === 'maximize') mainWindow?.isMaximized() ? mainWindow.unmaximize() : mainWindow?.maximize(); else mainWindow?.close(); return; }
      default: throw new Error('不支持的操作');
    }
  }
  ipcMain.handle('qinglan:command', async (event, name: keyof CommandMap, input: unknown) => {
    try {
      const frameUrl = event.senderFrame?.url || '';
      const trusted = frameUrl === pathToFileURL(path.join(app.getAppPath(), 'dist', 'index.html')).href || (!app.isPackaged && frameUrl === 'http://127.0.0.1:5178/');
      if (!trusted || event.sender !== mainWindow?.webContents || event.senderFrame !== event.sender.mainFrame) throw new Error('不允许的请求来源');
      return { ok: true, value: await command(name, input) };
    } catch (error) { return { ok: false, error: error instanceof z.ZodError ? '输入格式不正确，请检查必填内容' : safeMessage(error) }; }
  });
  if (process.env.QINGLAN_DEV_URL === 'http://127.0.0.1:5178') await mainWindow.loadURL(process.env.QINGLAN_DEV_URL);
  else await mainWindow.loadFile(path.join(app.getAppPath(), 'dist', 'index.html'));
  mainWindow.show(); social.start();
  let quitting = false;
  app.on('before-quit', event => {
    if (quitting) return; event.preventDefault(); quitting = true;
    jobs.cancelAll(); auth.cancel();
    void Promise.allSettled([rooms.stop(), social.shutdown()]).finally(() => app.quit());
    setTimeout(() => app.exit(), 4000).unref();
  });
  app.on('window-all-closed', () => app.quit());
}
