import fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { trustedUrl } from './safety';
import { exists, hashFile } from './files';
export const USER_AGENT = 'OLSLauncher/0.2.0 (Minecraft Java desktop launcher)';
export async function request(url: string, options: RequestInit = {}, signal?: AbortSignal): Promise<Response> {
  let current = trustedUrl(url).toString();
  for (let redirects = 0; redirects < 6; redirects++) {
    const headerTimeout = new AbortController();
    const timer = setTimeout(() => headerTimeout.abort(new Error('连接超时')), 45000);
    let response: Response;
    try { response = await fetch(current, { ...options, headers: { 'User-Agent': USER_AGENT, ...options.headers }, redirect: 'manual', signal: signal ? AbortSignal.any([signal, headerTimeout.signal]) : headerTimeout.signal }); }
    finally { clearTimeout(timer); }
    if (response.status >= 300 && response.status < 400 && response.headers.get('location')) {
      const next = trustedUrl(new URL(response.headers.get('location')!, current).toString()).toString();
      if (new URL(next).origin !== new URL(current).origin && options.headers && Object.keys(options.headers).some(x => x.toLowerCase() === 'authorization')) throw new Error('拒绝向其他站点转发凭证');
      await response.body?.cancel(); current = next; continue;
    }
    return response;
  }
  throw new Error('请求重定向次数过多');
}
export async function json<T>(url: string, options: RequestInit = {}, signal?: AbortSignal): Promise<T> {
  const response = await request(url, options, signal ? AbortSignal.any([signal, AbortSignal.timeout(45000)]) : AbortSignal.timeout(45000));
  if (!response.ok) {
    let reason = '';
    try { const value = await response.json() as { msg?: string; errorMessage?: string }; reason = value.msg || value.errorMessage || ''; } catch { /* no useful body */ }
    throw new Error(`${new URL(url).hostname} 返回 ${response.status}${reason ? `：${reason}` : ''}`);
  }
  return response.json() as Promise<T>;
}
export interface Download { url: string; file: string; hash?: string; algorithm?: 'sha1' | 'sha256' | 'sha512' | 'md5'; size?: number }
export async function download(item: Download, signal: AbortSignal, progress: (bytes: number, total: number) => void = () => {}) {
  trustedUrl(item.url);
  if (await exists(item.file)) {
    const stat = await fs.stat(item.file);
    if ((!item.size || stat.size === item.size) && item.hash && await hashFile(item.file, item.algorithm || 'sha1') === item.hash.toLowerCase()) { progress(stat.size, stat.size); return; }
  }
  await fs.mkdir(path.dirname(item.file), { recursive: true });
  for (let attempt = 0; attempt < 3; attempt++) {
    signal.throwIfAborted();
    const temp = `${item.file}.${randomUUID()}.part`;
    const idle = new AbortController(); let idleTimer: NodeJS.Timeout | undefined;
    const touch = () => { if (idleTimer) clearTimeout(idleTimer); idleTimer = setTimeout(() => idle.abort(new Error('下载长时间无响应')), 60000); };
    try {
      touch(); const response = await request(item.url, {}, AbortSignal.any([signal, idle.signal]));
      if (!response.ok || !response.body) throw new Error(`下载失败 (${response.status})：${path.basename(item.file)}`);
      const total = item.size || Number(response.headers.get('content-length')) || 0;
      const handle = await fs.open(temp, 'w');
      let bytes = 0;
      try {
        for await (const chunk of response.body as unknown as AsyncIterable<Uint8Array>) {
          signal.throwIfAborted(); touch(); bytes += chunk.length;
          if (bytes > 4 * 1024 ** 3 || (item.size && bytes > item.size)) throw new Error('下载文件大小异常');
          await handle.writeFile(chunk); progress(bytes, total);
        }
      } finally { await handle.close(); }
      if (item.size && bytes !== item.size) throw new Error('下载不完整，正在重试');
      if (item.hash && await hashFile(temp, item.algorithm || 'sha1') !== item.hash.toLowerCase()) throw new Error(`文件校验失败：${path.basename(item.file)}`);
      signal.throwIfAborted(); await fs.rename(temp, item.file); return;
    } catch (error) {
      await fs.rm(temp, { force: true });
      if (signal.aborted || attempt === 2) throw error;
      await new Promise<void>((resolve, reject) => {
        const done = () => { signal.removeEventListener('abort', abort); resolve(); };
        const timer = setTimeout(done, 600 * (attempt + 1));
        const abort = () => { clearTimeout(timer); reject(signal.reason); };
        signal.addEventListener('abort', abort, { once: true });
      });
    } finally { if (idleTimer) clearTimeout(idleTimer); }
  }
}
export async function parallel<T>(values: T[], concurrency: number, action: (value: T, index: number) => Promise<void>) {
  let index = 0; let error: unknown;
  await Promise.all(Array.from({ length: Math.min(concurrency, values.length) }, async () => {
    while (index < values.length && !error) { const current = index++; try { await action(values[current], current); } catch (caught) { error = caught; } }
  }));
  if (error) throw error;
}
