import fs from 'node:fs/promises';
import { gunzipSync } from 'node:zlib';
import type { World } from '../../shared/types';

/** Bounded Java NBT reader. Only world summary fields are retained. */
export function readLevelInfo(encoded: Buffer): Omit<World, 'folder'> {
  if (encoded.length > 8 * 1024 ** 2) throw new Error('level.dat 超出读取上限');
  const data = encoded[0] === 0x1f && encoded[1] === 0x8b ? gunzipSync(encoded, { maxOutputLength: 8 * 1024 ** 2 }) : encoded;
  let cursor = 0; let budget = 150000;
  const need = (size: number) => { if (size < 0 || !Number.isSafeInteger(size) || cursor + size > data.length) throw new Error('NBT 数据不完整'); };
  const u8 = () => { need(1); return data[cursor++]; };
  const i32 = () => { need(4); const value = data.readInt32BE(cursor); cursor += 4; return value; };
  const string = () => { need(2); const size = data.readUInt16BE(cursor); cursor += 2; need(size); const value = data.toString('utf8', cursor, cursor + size); cursor += size; return value; };
  const output: Record<string, string | number | boolean> = {};
  const wanted = new Set(['Data.LevelName', 'Data.LastPlayed', 'Data.GameType', 'Data.hardcore', 'Data.Version.Name', 'LevelName', 'LastPlayed', 'GameType', 'hardcore', 'Version.Name']);
  const value = (type: number, key: string, depth: number): void => {
    if (--budget < 0 || depth > 40) throw new Error('NBT 结构超出读取上限');
    const retain = wanted.has(key);
    if (type === 1) { const number = u8(); if (retain) output[key] = number; }
    else if (type === 2) { need(2); const number = data.readInt16BE(cursor); cursor += 2; if (retain) output[key] = number; }
    else if (type === 3) { const number = i32(); if (retain) output[key] = number; }
    else if (type === 4) { need(8); const number = Number(data.readBigInt64BE(cursor)); cursor += 8; if (retain && Number.isSafeInteger(number)) output[key] = number; }
    else if (type === 5 || type === 6) { const size = type === 5 ? 4 : 8; need(size); cursor += size; }
    else if (type === 8) { const text = string(); if (retain) output[key] = text; }
    else if (type === 7 || type === 11 || type === 12) { const count = i32(); const bytes = count * (type === 7 ? 1 : type === 11 ? 4 : 8); need(bytes); cursor += bytes; }
    else if (type === 9) { const childType = u8(); const count = i32(); if (count < 0 || count > budget || (count && childType === 0)) throw new Error('NBT 列表长度无效'); for (let index = 0; index < count; index++) value(childType, '', depth + 1); }
    else if (type === 10) { while (true) { const childType = u8(); if (!childType) break; const name = string(); value(childType, key ? `${key}.${name}` : name, depth + 1); } }
    else throw new Error('未知 NBT 类型');
  };
  if (u8() !== 10) throw new Error('level.dat 不是有效的 Java 存档');
  string(); value(10, '', 0);
  const get = (key: string) => output[`Data.${key}`] ?? output[key];
  const name = get('LevelName'); const version = get('Version.Name'); const played = get('LastPlayed'); const mode = get('GameType');
  return { name: typeof name === 'string' ? name.slice(0, 200) : '', gameVersion: typeof version === 'string' ? version.slice(0, 80) : undefined, lastPlayed: typeof played === 'number' ? played : undefined, gameMode: typeof mode === 'number' ? ['生存', '创造', '冒险', '旁观'][mode] || '未知' : undefined, hardcore: !!get('hardcore') };
}
export async function readWorld(file: string, folder: string): Promise<World> {
  try { const stat = await fs.stat(file); if (stat.size > 8 * 1024 ** 2) throw new Error(); const info = readLevelInfo(await fs.readFile(file)); return { ...info, folder, name: info.name || folder }; }
  catch { return { folder, name: folder, warning: '无法读取存档信息，保留文件夹名称' }; }
}
