import fs from 'node:fs/promises';
import path from 'node:path';
import { hashFile } from './files';
import { leafSchema } from './safety';
import type { Instance, Invite, ModFile, ModCheck } from '../../shared/types';
export async function modFiles(gameDir:string,ignoredHashes:string[]=[]):Promise<ModFile[]>{
  const directory=path.join(gameDir,'mods');let entries;
  try{const stat=await fs.lstat(directory);if(stat.isSymbolicLink()||!stat.isDirectory())throw new Error('模组目录不能是链接或普通文件');entries=await fs.readdir(directory,{withFileTypes:true});}catch(error){if((error as NodeJS.ErrnoException).code==='ENOENT')return [];throw error;}
  const result:ModFile[]=[];
  for(const entry of entries){if(!entry.name.toLowerCase().endsWith('.jar'))continue;
    const filename=leafSchema.parse(entry.name),file=path.join(directory,filename),before=await fs.lstat(file);
    if(before.isSymbolicLink()||!before.isFile())throw new Error('启用的模组必须是普通 JAR 文件，不能是链接');
    const sha512=await hashFile(file,'sha512');const after=await fs.lstat(file);
    if(before.size!==after.size||before.mtimeMs!==after.mtimeMs)throw new Error('模组正在被修改，请关闭其他程序后重试');
    if(!ignoredHashes.includes(sha512))result.push({filename,sha512,size:before.size});
    if(result.length>512)throw new Error('当前联机校验最多支持512个启用模组');
  }
  return result.sort((a,b)=>a.filename.localeCompare(b.filename));
}
export function compareMods(expected:ModFile[],actual:ModFile[]):ModCheck{
  const rest=[...actual];const missing:string[]=[];
  for(const file of expected){const index=rest.findIndex(item=>item.sha512===file.sha512&&item.size===file.size);if(index<0)missing.push(file.filename);else rest.splice(index,1);}
  return {compatible:!missing.length&&!rest.length,missing,extra:rest.map(item=>item.filename)};
}
export function versionCompatible(descriptor:Invite,instance:Instance){return instance.installed&&descriptor.gameVersion===instance.gameVersion&&descriptor.loader===instance.loader&&descriptor.loaderVersion===instance.loaderVersion;}
export function needsLocalEnvironment(instance:Instance,actual:ModFile[]){
  const platform=instance.resources.filter(item=>item.kind==='mod'&&item.enabled&&item.source!=='local');
  return instance.resources.some(item=>item.kind==='mod'&&item.enabled&&item.source==='local')||actual.some(file=>!platform.some(item=>item.filename===file.filename&&item.sha512===file.sha512))||platform.some(item=>!actual.some(file=>file.filename===item.filename&&file.sha512===item.sha512));
}
