export function trustedUrl(value: string): URL {
  const url = new URL(value);
  if (url.protocol !== 'https:' || url.username || url.password || (url.port && url.port !== '443') || !hosts.includes(url.hostname)) throw new Error(`不受信任的下载来源：${url.hostname}`);
  return url;
}
export function safeMessage(error: unknown) {
  const message = error instanceof Error ? error.message : String(error);
  return message.replace(/(Bearer\s+|access_token[=:]\s*|refresh_token[=:]\s*|NATFRP_TOKEN[=:]\s*)[^\s,;]+/gi, '$1[已隐藏]').slice(0, 600);
}
