import fs from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import type { Instance, ResourceKind, SearchResult, Resource } from '../../shared/types';
import { json, download } from './network';
import { identifier, leafSchema, under } from './safety';
import { exists } from './files';
import type { Store } from './store';
import type { JobContext } from './jobs';
import { sniffResource } from './local-scan';
interface ModVersion { id: string; project_id: string; name: string; version_number: string; game_versions: string[]; loaders: string[]; files: { filename: string; url: string; primary: boolean; size: number; hashes: { sha512: string } }[]; dependencies: { project_id?: string; version_id?: string; file_name?: string; dependency_type: string }[] }
const API = 'https://api.modrinth.com/v2';
export const resourceDirectory: Record<ResourceKind, string> = { mod: 'mods', shader: 'shaderpacks', resourcepack: 'resourcepacks' };
export class Modrinth {
  constructor(private store: Store) {}
  async search(input: { query: string; kind: ResourceKind; instanceId?: string; offset?: number; sort?: string }): Promise<SearchResult> {
    const facets = [[`project_type:${input.kind}`]];
    if (input.instanceId) {
      const instance = this.store.instance(input.instanceId); facets.push([`versions:${instance.gameVersion}`]);
      if (input.kind === 'mod' && instance.loader !== 'vanilla') facets.push([`categories:${instance.loader}`]);
    }
    const params = new URLSearchParams({ query: input.query, facets: JSON.stringify(facets), limit: '12', offset: String(input.offset || 0), index: input.sort || 'downloads' });
    return json<SearchResult>(`${API}/search?${params}`);
  }
  async install(instance: Instance, projectId: string, kind: ResourceKind, context: JobContext, versionId?: string) {
    if (this.store.state.running.includes(instance.id)) throw new Error('请先退出该游戏，再修改资源');
    if (!instance.installed) throw new Error('请先完成游戏安装');
    if ((kind === 'mod' || kind === 'shader') && instance.loader !== 'fabric') throw new Error('模组和光影需要 Fabric 实例，请在游戏库新建 Fabric 游戏');
    const plan = new Map<string, { version: ModVersion; kind: ResourceKind; name: string }>();
    const existing = new Map(instance.resources.map(resource => [resource.projectId, resource]));
    const visiting = new Set<string>();
    const resolve = async (project: string | undefined, resourceKind: ResourceKind, exact?: string) => {
      context.signal.throwIfAborted(); if (project) identifier.parse(project); if (exact) identifier.parse(exact);
      let version: ModVersion;
      if (exact) version = await json<ModVersion>(`${API}/version/${encodeURIComponent(exact)}`, {}, context.signal);
      else {
        const loaders = resourceKind === 'mod' ? ['fabric'] : resourceKind === 'shader' ? ['iris'] : ['minecraft'];
        const params = new URLSearchParams({ game_versions: JSON.stringify([instance.gameVersion]), loaders: JSON.stringify(loaders), include_changelog: 'false' });
        const versions = await json<ModVersion[]>(`${API}/project/${encodeURIComponent(project!)}/version?${params}`, {}, context.signal);
        if (!versions.length) throw new Error(`未找到适合 ${instance.gameVersion} 的资源：${project}`);
        version = versions[0];
      }
      if (!version.game_versions.includes(instance.gameVersion) || (resourceKind === 'mod' && !version.loaders.includes('fabric'))) throw new Error(`资源 ${version.name} 与游戏版本或加载器不兼容`);
      if (project && project.length === 8 && version.project_id !== project) throw new Error('资源版本归属不匹配');
      const previous = plan.get(version.project_id);
      if (previous) { if (previous.version.id !== version.id) throw new Error(`模组依赖版本冲突：${version.name}`); return; }
      if (visiting.has(version.project_id)) return; visiting.add(version.project_id);
      const projectInfo = await json<{ title: string; project_type: string }>(`${API}/project/${version.project_id}`, {}, context.signal);
      if (projectInfo.project_type !== resourceKind) throw new Error('资源类型不匹配');
      plan.set(version.project_id, { version, kind: resourceKind, name: projectInfo.title });
      for (const dependency of version.dependencies) {
        if (dependency.dependency_type === 'required') {
          if (!dependency.project_id && !dependency.version_id) throw new Error(`需要手动安装的依赖：${dependency.file_name || '未知文件'}`);
          await resolve(dependency.project_id, 'mod', dependency.version_id);
        }
      }
    };
    context.update('分析兼容版本与必要依赖', 0.02);
    await resolve(projectId, kind, versionId);
    if (kind === 'shader') await resolve('iris', 'mod');
    for (const { version } of plan.values()) for (const dependency of version.dependencies.filter(d => d.dependency_type === 'incompatible')) {
      if (dependency.project_id && (plan.has(dependency.project_id) || existing.get(dependency.project_id)?.enabled)) throw new Error(`检测到不兼容的已安装模组：${dependency.project_id}`);
      if (dependency.version_id && [...instance.resources, ...[...plan.values()].map(p => ({ versionId: p.version.id }))].some(r => r.versionId === dependency.version_id)) throw new Error('检测到不兼容的模组版本');
    }
    const staged: { resource: Resource; file: string }[] = [];
    let count = 0;
    for (const { version, kind: type, name } of plan.values()) {
      const file = version.files.find(file => file.primary) || version.files[0];
      if (!file || !/^[a-f0-9]{128}$/i.test(file.hashes.sha512)) throw new Error('资源缺少可靠的文件校验值');
      leafSchema.parse(file.filename);
      if (!file.filename.toLowerCase().endsWith(type === 'mod' ? '.jar' : '.zip')) throw new Error('资源文件类型不受支持');
      const target = this.store.file('cache', 'modrinth', `${identifier.parse(version.id)}-${file.filename}`);
      await download({ url: file.url, file: target, hash: file.hashes.sha512, algorithm: 'sha512', size: file.size }, context.signal, (bytes, total) => context.update(`下载 ${name}`, 0.05 + (count + (total ? bytes / total : 0)) / plan.size * 0.8, bytes, total));
      const metadata = type === 'mod' ? await sniffResource(this.store.file('cache'), 'modrinth', `${version.id}-${file.filename}`, type) : undefined;
      staged.push({ file: target, resource: { projectId: version.project_id, versionId: version.id, name, filename: file.filename, kind: type, sha512: file.hashes.sha512, enabled: true, source: 'modrinth', modId: metadata?.modId, displayVersion: metadata?.version } }); count++;
    }
    context.signal.throwIfAborted(); context.update('应用资源文件', 0.95);
    const backupDirectory = this.store.file('backups', instance.id, randomUUID());
    const moves: { from: string; backup: string }[] = []; const created: string[] = [];
    const previousResources = [...instance.resources];
    try {
      for (const { file, resource } of staged) {
        const dir = under(this.store.instanceDir(instance.id), resourceDirectory[resource.kind]);
        await fs.mkdir(dir, { recursive: true });
        const old = existing.get(resource.projectId) || instance.resources.find(item => item.source === 'local' && item.kind === resource.kind && (item.filename === resource.filename || !!resource.modId && item.modId === resource.modId));
        const target = under(dir, resource.filename);
        const backupCandidates = new Set([target, ...(old ? [under(dir, `${leafSchema.parse(old.filename)}${old.enabled ? '' : '.disabled'}`)] : [])]);
        for (const from of backupCandidates) if (await exists(from)) {
          await fs.mkdir(backupDirectory, { recursive: true }); const backup = under(backupDirectory, `${moves.length}-${randomUUID()}`);
          await fs.rename(from, backup); moves.push({ from, backup });
        }
        await fs.copyFile(file, target); created.push(target);
        instance.resources = [...instance.resources.filter(r => r.projectId !== resource.projectId && r.projectId !== old?.projectId), resource];
      }
      await this.store.save();
    } catch (error) {
      instance.resources = previousResources;
      for (const file of created) await fs.rm(file, { force: true });
      for (const move of moves.reverse()) await fs.rename(move.backup, move.from);
      throw error;
    }
    context.update('资源已安装', 1);
  }
  async toggle(instanceId: string, projectId: string) {
    if (this.store.state.running.includes(instanceId)) throw new Error('请先退出游戏，再启用或停用模组');
    const instance = this.store.instance(instanceId); const resource = instance.resources.find(r => r.projectId === projectId);
    if (!resource) throw new Error('没有找到这个资源');
    const dir = under(this.store.instanceDir(instanceId), resourceDirectory[resource.kind]);
    const filename = leafSchema.parse(resource.filename);
    const from = under(dir, `${filename}${resource.enabled ? '' : '.disabled'}`); const to = under(dir, `${filename}${resource.enabled ? '.disabled' : ''}`);
    if (await exists(to)) throw new Error('目标文件已存在，请先在文件夹中检查重复文件');
    await fs.rename(from, to); resource.enabled = !resource.enabled;
    try { await this.store.save(); } catch (error) { resource.enabled = !resource.enabled; await fs.rename(to, from); throw error; }
  }
}
