import fs from 'node:fs/promises';
import path from 'node:path';
import { createReadStream, constants } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { atomicWrite, exists } from './files';
import type { JobContext } from './jobs';
export interface StoragePlan { id: string; source: string; target: string; bytes: number; files: number; createdAt: number }
const marker='.ols-migration.json';
function overlaps(a:string,b:string){const rel=path.relative(a,b);return !rel||(!rel.startsWith(`..${path.sep}`)&&rel!=='..'&&!path.isAbsolute(rel));}
export async function storageRoot(userData:string){
  const pointer=path.join(userData,'storage.json');if(!await exists(pointer))return path.join(userData,'data');
  const value=JSON.parse(await fs.readFile(pointer,'utf8')) as {schema:number;root:string};
  if(value.schema!==1||typeof value.root!=='string'||!path.isAbsolute(value.root))throw new Error('存储位置配置无效，请检查 storage.json');
  const info=await fs.lstat(value.root).catch(()=>undefined);
  if(!info?.isDirectory()||info.isSymbolicLink()||!await exists(path.join(value.root,'state.json')))throw new Error(`游戏存储位置不可用，请连接磁盘后重试：${value.root}`);
  if(await exists(path.join(value.root,marker)))throw new Error('目标目录包含未完成的迁移，请保留备份并检查存储位置');
  return value.root;
}
async function manifest(root:string,signal?:AbortSignal){
  const result:{name:string;size:number;mtime:number}[]=[];const directories:string[]=[];let bytes=0,nodes=0;
  async function walk(directory:string,depth=0){if(depth>50)throw new Error('数据目录层级过深');for(const entry of await fs.readdir(directory,{withFileTypes:true})){
    signal?.throwIfAborted();if(++nodes>1000000)throw new Error('数据文件数量超过迁移上限');const file=path.join(directory,entry.name);const info=await fs.lstat(file);
    if(info.isSymbolicLink())throw new Error('数据目录包含链接，请先处理链接后再迁移');
    if(info.isDirectory()){directories.push(path.relative(root,file));await walk(file,depth+1);}else if(info.isFile()){const name=path.relative(root,file);if(name===marker)throw new Error('源目录包含未完成的迁移记录');bytes+=info.size;result.push({name,size:info.size,mtime:info.mtimeMs});}else throw new Error('数据目录包含不支持的文件类型');
  }}
  await walk(root);result.sort((a,b)=>a.name.localeCompare(b.name));directories.sort();return {result,bytes,directories};
}
async function validateTarget(source:string,target:string){
  source=await fs.realpath(source);const parent=await fs.realpath(path.dirname(target));target=path.join(parent,path.basename(target));
  if(overlaps(source,target)||overlaps(target,source))throw new Error('新位置不能与当前数据目录相同或互相嵌套');
  if(await exists(target)){const stat=await fs.lstat(target);if(!stat.isDirectory()||stat.isSymbolicLink()||(await fs.readdir(target)).length)throw new Error('目标 OLSData 目录必须为空，不能覆盖已有游戏或旧备份');}
  return {source,target,parent};
}
export async function prepareStorage(source:string,target:string):Promise<StoragePlan>{
  const location=await validateTarget(source,target);const data=await manifest(location.source);
  const disk=await fs.statfs(location.parent);if(Number(disk.bavail)*Number(disk.bsize)<data.bytes+64*1024*1024)throw new Error('目标磁盘空间不足，需要容纳全部现有数据及64MB余量');
  return {id:randomUUID(),source:location.source,target:location.target,bytes:data.bytes,files:data.result.length,createdAt:Date.now()};
}
async function digest(file:string,signal:AbortSignal){const hash=createHash('sha256');for await(const chunk of createReadStream(file)){signal.throwIfAborted();hash.update(chunk);}return hash.digest('hex');}
export async function migrateStorage(plan:StoragePlan,context:JobContext,commit:(target:string)=>Promise<void>){
  const location=await validateTarget(plan.source,plan.target);const {result,bytes,directories}=await manifest(location.source,context.signal);
  const disk=await fs.statfs(location.parent);if(Number(disk.bavail)*Number(disk.bsize)<bytes+64*1024*1024)throw new Error('目标磁盘空间不足');
  context.signal.throwIfAborted();await fs.mkdir(location.target,{recursive:true});
  const markerFile=path.join(location.target,marker);await atomicWrite(markerFile,JSON.stringify({source:location.source,status:'copying'}));
  let copied=0;
  try{
    for(const directory of directories){context.signal.throwIfAborted();await fs.mkdir(path.join(location.target,directory),{recursive:true});}
    for(const [index,item] of result.entries()){
      context.signal.throwIfAborted();const source=path.join(location.source,item.name),destination=path.join(location.target,item.name);
      const before=await fs.lstat(source);if(!before.isFile()||before.isSymbolicLink()||before.size!==item.size||before.mtimeMs!==item.mtime)throw new Error('源数据发生变化，请关闭其他启动器后重新迁移');
      await fs.mkdir(path.dirname(destination),{recursive:true});await fs.copyFile(source,destination,constants.COPYFILE_EXCL);
      if(await digest(source,context.signal)!==await digest(destination,context.signal))throw new Error(`复制校验失败：${item.name}`);
      const after=await fs.lstat(source);if(after.size!==item.size||after.mtimeMs!==item.mtime)throw new Error('迁移期间源文件发生变化');
      copied+=item.size;context.update(`复制并校验 ${index+1} / ${result.length}`,bytes?copied/bytes:index/result.length,copied,bytes);
    }
    // Verify that no new/deleted files appeared during the copy.
    const latest=await manifest(location.source,context.signal);if(JSON.stringify(latest.result)!==JSON.stringify(result)||JSON.stringify(latest.directories)!==JSON.stringify(directories))throw new Error('源数据目录发生变化，请重试');
    context.signal.throwIfAborted();context.beginCommit?.();context.update('文件已校验，正在切换位置（此步骤不可取消）',.99);
    await fs.rm(markerFile);await commit(location.target);
    context.update('存储位置已切换，旧目录保留为备份',1);
  }catch(error){await atomicWrite(markerFile,JSON.stringify({source:location.source,status:'incomplete'})).catch(()=>{});throw error;}
}
