import { spawn } from 'node:child_process';
import fs from 'node:fs/promises';
import { json, download } from './network';
import type { Store } from './store';
import type { JobContext } from './jobs';
import type { SakuraAccount, SakuraNode, SakuraTunnel, DataPlan } from '../../shared/types';
const API = 'https://api.natfrp.com/v4';
export class Sakura {
  private process?: ReturnType<typeof spawn>;
  onExit: () => void = () => {};
  constructor(private store: Store) {}
  private token() { const token = this.store.secret('sakura'); if (!token) throw new Error('请先在樱花账户页绑定访问密钥'); return token; }
  private call<T>(route: string, method = 'GET', body?: unknown, token = this.token()) {
    return json<T>(`${API}${route}`, { method, headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
  }
  async saveToken(token: string) {
    const account = await this.call<SakuraAccount>('/user/info', 'GET', undefined, token);
    if (account.ban) throw new Error(`${account.ban.title}：${account.ban.reason}`);
    await this.store.setSecret('sakura', token); this.store.state.sakuraConfigured = true; this.store.changed();
  }
  async logout() { this.stop(); await this.store.setSecret('sakura'); this.store.state.sakuraConfigured = false; this.store.changed(); }
  async account() {
    const raw = await this.call<SakuraAccount & { token?: string }>('/user/info');
    // Explicit projection: the upstream returns the secret token with account information.
    const account: SakuraAccount = { id: raw.id, name: raw.name, speed: raw.speed, tunnels: raw.tunnels, realname: raw.realname, group: raw.group, traffic: raw.traffic, sign: raw.sign, ban: raw.ban };
    if (account.ban) throw new Error(`${account.ban.title}：${account.ban.reason}`);
    const plans = await this.call<DataPlan[]>('/user/data_plans?status=valid'); return { account, plans };
  }
  async nodes(): Promise<SakuraNode[]> {
    const raw = await this.call<Record<string, Omit<SakuraNode, 'id' | 'available'>>>('/nodes');
    return Object.entries(raw).map(([id, node]) => ({ ...node, id: Number(id), available: !!(node.flag & 4) && !(node.flag & 512) && !(node.flag & 256) }));
  }
  tunnels() { return this.call<SakuraTunnel[]>('/tunnels'); }
  async prepare(instanceId: string, nodeId: number, port: number, tunnelId?: number) {
    const nodes = await this.nodes(); const node = nodes.find(n => n.id === nodeId);
    if (!node || !node.available) throw new Error('此节点当前不可用，或要求额外访问认证，请选择可用节点');
    const note = `OLS:${instanceId}`;
    let tunnel = (await this.tunnels()).find(t => tunnelId ? t.id === tunnelId : [note, `Qinglan:${instanceId}`].includes(t.note) && t.node === nodeId && t.type === 'tcp');
    if (tunnelId && !tunnel) throw new Error('指定隧道不存在');
    if (tunnel && (tunnel.type !== 'tcp' || tunnel.node !== nodeId || tunnel.status !== 0)) throw new Error('请选择相同节点的正常 TCP 隧道');
    if (tunnel) {
      if (tunnel.online) throw new Error('这个隧道已在其他客户端运行，请先停止或选择新隧道');
      await this.call('/tunnel/edit', 'POST', { id: tunnel.id, local_ip: '127.0.0.1', local_port: port, extra: 'minecraft_detect = disabled' });
    } else {
      const created = await this.call<{ id: number }>('/tunnels', 'POST', { name: `ols_${instanceId.slice(0, 8)}`, type: 'tcp', node: nodeId, local_ip: '127.0.0.1', local_port: port, note, extra: 'minecraft_detect = disabled' });
      tunnel = (await this.tunnels()).find(t => t.id === created.id);
      if (!tunnel) throw new Error('隧道已创建，但暂时无法读取，请刷新账户页后重试');
    }
    const remotePort = Number(tunnel.remote);
    if (!Number.isInteger(remotePort) || remotePort < 1 || remotePort > 65535) throw new Error('樱花返回的远程端口不正确');
    return { tunnelId: tunnel.id, host: node.host, port: remotePort };
  }
  async start(tunnelId: number, context: JobContext) {
    if (this.process) throw new Error('已有穿透进程正在运行');
    context.update('准备樱花穿透客户端', 0.55);
    const clients = await json<{ frpc: { ver: string; archs: Record<string, { url: string; hash: string; size: number }> } }>(`${API}/system/clients?download=true`, {}, context.signal);
    const entry = clients.frpc.archs.windows_amd64;
    if (!entry || !/^[a-f0-9]{32}$/i.test(entry.hash)) throw new Error('官方 frpc 下载信息无效');
    const executable = this.store.file('tools', `frpc-${entry.hash}.exe`);
    await download({ url: entry.url, file: executable, hash: entry.hash, algorithm: 'md5', size: entry.size }, context.signal, (bytes, total) => context.update('下载樱花穿透客户端', 0.55 + (total ? bytes / total : 0) * 0.1, bytes, total));
    context.signal.throwIfAborted();
    const token = this.token(); const cwd = this.store.file('frpc'); await fs.mkdir(cwd, { recursive: true });
    // Pass the key via environment, never via command line or logs.
    const child = spawn(executable, ['--disable_log_color', '--no_check_update'], { cwd, env: { ...process.env, NATFRP_TOKEN: token, NATFRP_TARGET: String(tunnelId) }, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    this.process = child;
    let output = '';
    const receive = (chunk: Buffer) => { output += chunk.toString().replaceAll(token, '[凭证已隐藏]'); if (output.length > 8000) output = output.slice(-8000); };
    child.stdout?.on('data', receive); child.stderr?.on('data', receive);
    child.once('exit', () => { if (this.process === child) { this.process = undefined; this.onExit(); } });
    try {
      await new Promise<void>((resolve, reject) => { child.once('spawn', resolve); child.once('error', reject); });
      for (let i = 0; i < 30; i++) {
        context.signal.throwIfAborted();
        if (child.exitCode !== null || this.process !== child) throw new Error(`樱花穿透启动失败：${output.slice(-400)}`);
        if ((await this.tunnels()).some(t => t.id === tunnelId && t.online)) { context.update('隧道已连接', 0.95); return; }
        await new Promise(resolve => setTimeout(resolve, 1500));
      }
      throw new Error(`隧道连接超时，请检查账户和节点。${output.slice(-300)}`);
    } catch (error) { this.stop(); throw error; }
  }
  stop() { const child = this.process; this.process = undefined; child?.kill(); }
  async delete(id: number) {
    if (this.store.state.room.tunnelId === id && this.store.state.room.state !== 'idle') throw new Error('请先关闭当前世界，再删除隧道');
    const result = await this.call<{ deleted: number[]; failed: number[] }>('/tunnel/delete', 'POST', { ids: String(id) });
    if (!result.deleted.includes(id)) throw new Error('隧道未能删除，请刷新后重试');
  }
}
