import fs from 'node:fs';
import path from 'node:path';
import { safeStorage } from 'electron';
import { z } from 'zod';
import { atomicWrite, exists, readJson } from './files';
import { identifier, under } from './safety';
import type { AppState, Settings, Instance, Account } from '../../shared/types';
export const settingsSchema = z.object({
  memoryMb: z.number().int().min(1024).max(32768), javaPath: z.string().max(1000), autoJava: z.boolean(),
  microsoftClientId: z.string().max(100).refine(v => !v || /^[a-f0-9-]{36}$/i.test(v), 'Client ID 格式不正确'),
  concurrency: z.number().int().min(1).max(12), friendsServer: z.string().max(500), theme: z.enum(['light', 'dark']),
  textScale: z.number().min(1).max(1.5).default(1), reduceMotion: z.boolean().default(false),
  backgroundRevision: z.string().uuid().optional(), backgroundDim: z.number().min(0.35).max(0.9).default(0.75)
});
interface SavedState { schema: 1; settings: Settings; selectedId?: string; instances: Instance[]; account?: Account }
export class Store {
  state: AppState;
  onChange: () => void = () => {};
  private writing: Promise<void> = Promise.resolve();
  constructor(public root: string) {
    this.state = { instances: [], settings: { memoryMb: 4096, javaPath: '', autoJava: true, microsoftClientId: '', concurrency: 6, friendsServer: 'http://127.0.0.1:4589', theme: 'light' },
      social: { connected: false, friends: [] }, sakuraConfigured: false, dataDir: root, jobs: [], room: { state: 'idle', detail: '' }, running: [], logs: [], appVersion: '0.4.0' };
  }
  async init() {
    fs.mkdirSync(this.root, { recursive: true });
    if (await exists(this.file('state.json'))) {
      const value = await readJson<SavedState>(this.file('state.json'));
      if (value.schema !== 1 || !Array.isArray(value.instances)) throw new Error('配置文件版本不受支持，请备份后检查 state.json');
      this.state.settings = settingsSchema.parse({ ...this.state.settings, ...value.settings });
      this.state.instances = value.instances.map(item => ({ ...item, id: identifier.parse(item.id), gameVersion: identifier.parse(item.gameVersion), versionId: identifier.parse(item.versionId), ...(item.importState === 'copying' ? { importState: 'failed' as const, installed: false } : {}) }));
      this.state.selectedId = value.selectedId; this.state.account = value.account;
    }
    this.state.sakuraConfigured = !!this.secret('sakura');
  }
  file(...parts: string[]) { return under(this.root, ...parts); }
  async flush() { await this.writing; }
  instance(id: string) { const instance = this.state.instances.find(item => item.id === id); if (!instance) throw new Error('游戏实例不存在'); return instance; }
  instanceDir(id: string) { return this.file('instances', identifier.parse(id)); }
  changed() { this.onChange(); }
  async save() {
    const snapshot: SavedState = { schema: 1, settings: this.state.settings, instances: this.state.instances, selectedId: this.state.selectedId, account: this.state.account };
    const encoded = JSON.stringify(snapshot, null, 2);
    this.writing = this.writing.catch(() => {}).then(() => atomicWrite(this.file('state.json'), encoded));
    await this.writing; this.changed();
  }
  secret(key: string): string | undefined {
    const file = this.file('secrets', `${identifier.parse(key)}.bin`);
    if (!fs.existsSync(file)) return undefined;
    if (!safeStorage.isEncryptionAvailable()) throw new Error('系统凭证加密不可用');
    return safeStorage.decryptString(fs.readFileSync(file));
  }
  async setSecret(key: string, value?: string) {
    const file = this.file('secrets', `${identifier.parse(key)}.bin`);
    if (!value) { this.writing=this.writing.catch(()=>{}).then(()=>import('node:fs/promises').then(m => m.rm(file, { force: true }))); await this.writing; return; }
    if (!safeStorage.isEncryptionAvailable()) throw new Error('系统凭证加密不可用，无法保存登录状态');
    const encrypted=safeStorage.encryptString(value);
    this.writing=this.writing.catch(()=>{}).then(()=>atomicWrite(file,encrypted));await this.writing;
  }
  log(value: string) {
    this.state.logs.push(`${new Date().toLocaleTimeString('zh-CN', { hour12: false })}  ${value}`);
    this.state.logs = this.state.logs.slice(-150); this.changed();
  }
}
