import { deflateRawSync, inflateRawSync } from 'node:zlib';
import { createHash, timingSafeEqual } from 'node:crypto';
import { z } from 'zod';
import { identifier, leafSchema } from './safety';
import type { Invite } from '../../shared/types';
export const inviteSchema = z.object({
  schema: z.union([z.literal(1),z.literal(2)]), name: z.string().min(1).max(80),
  host: z.string().min(1).max(253).regex(/^(?=.{1,253}$)[a-zA-Z0-9](?:[a-zA-Z0-9.-]*[a-zA-Z0-9])?$/).refine(v => !v.includes('..')),
  port: z.number().int().min(1).max(65535), gameVersion: identifier,
  loader: z.enum(['vanilla', 'fabric']), loaderVersion: identifier.optional(),
  expiresAt: z.number().int().positive(), mods: z.array(z.object({ projectId: identifier, versionId: identifier }).strict()).max(200),
  localMods:z.array(z.object({filename:leafSchema,sha512:z.string().regex(/^[a-f0-9]{128}$/),size:z.number().int().min(0).max(2**40)}).strict()).min(1).max(512).optional()
}).strict().superRefine((value,context)=>{
  if((value.schema===1&&value.localMods)||(value.schema===2&&(!value.localMods||value.loader!=='fabric')))context.addIssue({code:z.ZodIssueCode.custom,message:'本地模组房间需要新版协议与Fabric环境'});
});
export function encodeInvite(input: Invite): string {
  const data = deflateRawSync(Buffer.from(JSON.stringify(inviteSchema.parse(input)))).toString('base64url');
  const check = createHash('sha256').update(data).digest('hex').slice(0, 12);
  return `QL1.${data}.${check}`;
}
export function decodeInvite(code: string, now = Date.now()): Invite {
  if (code.length > 24000) throw new Error('邀请码过长');
  const match = code.trim().match(/^(?:启源联机\s*)?(QL1\.([A-Za-z0-9_-]+)\.([a-f0-9]{12}))$/);
  if (!match) throw new Error('邀请码格式不正确，请复制完整的 QL1 开头文本');
  const expected = createHash('sha256').update(match[2]).digest('hex').slice(0, 12);
  if (!timingSafeEqual(Buffer.from(expected), Buffer.from(match[3]))) throw new Error('邀请码不完整或已损坏');
  let data: Invite;
  try { data = inviteSchema.parse(JSON.parse(inflateRawSync(Buffer.from(match[2], 'base64url'), { maxOutputLength: 256000 }).toString())); }
  catch { throw new Error('邀请码内容无效或版本不受支持'); }
  if (data.expiresAt < now) throw new Error('邀请码已过期，请让房主重新创建房间');
  if (data.expiresAt > now + 7 * 86400000) throw new Error('邀请码有效期异常');
  if (data.loader === 'fabric' && !data.loaderVersion) throw new Error('邀请码缺少 Fabric 版本');
  if (data.loader === 'vanilla' && data.mods.length) throw new Error('原版实例不能包含模组');
  return data;
}
