import fs from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import path from 'node:path';
import AdmZip from 'adm-zip';
import { under } from './safety';
export async function exists(file: string) { try { await fs.access(file); return true; } catch { return false; } }
export async function atomicWrite(file: string, value: string | Buffer) {
  await fs.mkdir(path.dirname(file), { recursive: true });
  const temp = `${file}.${randomUUID()}.tmp`;
  try { await fs.writeFile(temp, value, { mode: 0o600 }); await fs.rename(temp, file); }
  finally { await fs.rm(temp, { force: true }); }
}
export async function readJson<T>(file: string): Promise<T> { return JSON.parse(await fs.readFile(file, 'utf8')); }
export async function hashFile(file: string, algorithm: string) {
  const hash = createHash(algorithm);
  for await (const chunk of createReadStream(file)) hash.update(chunk);
  return hash.digest('hex');
}
export async function extractZip(file: string, target: string, skipMeta = false) {
  const zip = new AdmZip(file);
  let total = 0;
  for (const entry of zip.getEntries()) {
    const name = entry.entryName.replace(/\\/g, '/');
    if (skipMeta && name.startsWith('META-INF/')) continue;
    if (name.startsWith('/') || name.split('/').some(s => s === '..' || s.includes(':')) || ((entry.attr >>> 16) & 0o170000) === 0o120000) throw new Error('压缩包包含不安全路径');
    total += entry.header.size;
    if (total > 2 * 1024 ** 3) throw new Error('压缩包解压体积超出限制');
    const destination = under(target, name);
    if (entry.isDirectory) await fs.mkdir(destination, { recursive: true });
    else { await fs.mkdir(path.dirname(destination), { recursive: true }); await fs.writeFile(destination, entry.getData()); }
  }
}
