import { request, json } from './network';
import type { Store } from './store';
import type { DeviceCode } from '../../shared/types';
const BASE = 'https://login.microsoftonline.com/consumers/oauth2/v2.0';
const SCOPE = 'XboxLive.signin offline_access';
interface MicrosoftTokens { access_token: string; refresh_token: string; error?: string; error_description?: string }
interface MinecraftSession { accessToken: string; expiresAt: number; id: string; name: string; refreshToken: string; clientId: string }
export class Auth {
  private pending?: AbortController;
  constructor(private store: Store) {}
  cancel() { this.pending?.abort(); this.pending = undefined; }
  async login(): Promise<DeviceCode> {
    const clientId = this.store.state.settings.microsoftClientId;
    if (!clientId) throw new Error('请先在设置中填写启动器的 Microsoft 应用 Client ID');
    this.cancel(); const controller = new AbortController(); this.pending = controller;
    const code = await json<{ device_code: string; user_code: string; verification_uri: string; expires_in: number; interval: number }>(`${BASE}/devicecode`, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ client_id: clientId, scope: SCOPE }).toString() }, controller.signal);
    const expiresAt = Date.now() + code.expires_in * 1000;
    void this.poll(code.device_code, clientId, code.interval || 5, expiresAt, controller.signal).catch(error => {
      if (!controller.signal.aborted) this.store.log(`微软登录：${error instanceof Error ? error.message : '登录失败'}`);
    });
    return { userCode: code.user_code, verificationUri: code.verification_uri, expiresAt };
  }
  private async poll(deviceCode: string, clientId: string, interval: number, expiresAt: number, signal: AbortSignal) {
    let delay = Math.max(5, interval);
    while (Date.now() < expiresAt) {
      await new Promise<void>((resolve, reject) => {
        const timer = setTimeout(() => { signal.removeEventListener('abort', abort); resolve(); }, delay * 1000);
        const abort = () => { clearTimeout(timer); reject(new Error('登录已取消')); }; signal.addEventListener('abort', abort, { once: true });
      });
      signal.throwIfAborted();
      const response = await request(`${BASE}/token`, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ client_id: clientId, grant_type: 'urn:ietf:params:oauth:grant-type:device_code', device_code: deviceCode }).toString() }, signal);
      const result = await response.json() as MicrosoftTokens;
      if (result.error === 'authorization_pending') continue;
      if (result.error === 'slow_down') { delay += 5; continue; }
      if (result.error || !response.ok) throw new Error(result.error === 'authorization_declined' ? '已取消授权' : `微软授权未完成：${result.error || response.status}`);
      await this.exchange(result, clientId, signal); return;
    }
    throw new Error('登录码已过期，请重新登录');
  }
  private async exchange(tokens: MicrosoftTokens, clientId: string, signal?: AbortSignal): Promise<MinecraftSession> {
    const post = <T>(url: string, body: unknown) => json<T>(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }, signal);
    const xbox = await post<{ Token: string }>('https://user.auth.xboxlive.com/user/authenticate', { Properties: { AuthMethod: 'RPS', SiteName: 'user.auth.xboxlive.com', RpsTicket: `d=${tokens.access_token}` }, RelyingParty: 'http://auth.xboxlive.com', TokenType: 'JWT' });
    const xsts = await post<{ Token: string; DisplayClaims: { xui: { uhs: string }[] } }>('https://xsts.auth.xboxlive.com/xsts/authorize', { Properties: { SandboxId: 'RETAIL', UserTokens: [xbox.Token] }, RelyingParty: 'rp://api.minecraftservices.com/', TokenType: 'JWT' });
    const minecraft = await post<{ access_token: string; expires_in: number }>('https://api.minecraftservices.com/authentication/login_with_xbox', { identityToken: `XBL3.0 x=${xsts.DisplayClaims.xui[0].uhs};${xsts.Token}` });
    const headers = { Authorization: `Bearer ${minecraft.access_token}` };
    const profile = await json<{ id: string; name: string }>('https://api.minecraftservices.com/minecraft/profile', { headers }, signal).catch(() => { throw new Error('无法读取 Minecraft Java 档案，请确认已拥有 Java 版且应用有 Minecraft API 权限'); });
    signal?.throwIfAborted();
    const session: MinecraftSession = { id: profile.id, name: profile.name, accessToken: minecraft.access_token, expiresAt: Date.now() + minecraft.expires_in * 1000, refreshToken: tokens.refresh_token, clientId };
    await this.store.setSecret('microsoft', JSON.stringify(session));
    this.store.state.account = { id: profile.id, name: profile.name }; await this.store.save();
    this.store.log(`${profile.name} 已登录 Minecraft`); return session;
  }
  async session(): Promise<MinecraftSession> {
    const stored = this.store.secret('microsoft'); if (!stored) throw new Error('请先登录正版 Microsoft / Minecraft 账号');
    const value = JSON.parse(stored) as MinecraftSession;
    if (value.expiresAt > Date.now() + 120000) return value;
    const result = await json<MicrosoftTokens>(`${BASE}/token`, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ client_id: value.clientId, grant_type: 'refresh_token', refresh_token: value.refreshToken, scope: SCOPE }).toString() });
    return this.exchange({ ...result, refresh_token: result.refresh_token || value.refreshToken }, value.clientId);
  }
  async logout() { this.cancel(); await this.store.setSecret('microsoft'); this.store.state.account = undefined; await this.store.save(); }
}
