import fs from 'node:fs/promises';
import path from 'node:path';
import net from 'node:net';
import type { Store } from './store';
import type { Minecraft } from './minecraft';
import type { Modrinth } from './modrinth';
import type { Sakura } from './sakura';
import type { Social } from './social';
import type { JobContext } from './jobs';
import type { Invite } from '../../shared/types';
import { exists, hashFile } from './files';
import { modFiles, needsLocalEnvironment, compareMods, versionCompatible } from './local-multiplayer';
import type { ModCheck } from '../../shared/types';
import { leafSchema } from './safety';
export function tcpAvailable(port: number, host = '127.0.0.1') {
  return new Promise<boolean>(resolve => {
    const socket = net.createConnection({ host, port });
    const finish = (value: boolean) => { socket.destroy(); resolve(value); };
    socket.setTimeout(1500); socket.once('connect', () => finish(true)); socket.once('error', () => finish(false)); socket.once('timeout', () => finish(false));
  });
}
export class Rooms {
  private controller?: AbortController; private monitor?: NodeJS.Timeout; private epoch = 0;
  constructor(private store: Store, private minecraft: Minecraft, private mods: Modrinth, private sakura: Sakura, private social: Social, private bundled: string) {
    minecraft.onExit = id => { if (store.state.room.instanceId === id) void this.stop(); };
    minecraft.onWorldClosed = minecraft.onExit;
    sakura.onExit = () => { if (store.state.room.state === 'ready') { void this.stop().then(() => { store.state.room = { state: 'error', detail: '樱花连接已断开，世界已从好友列表撤下' }; store.changed(); }); } };
  }
  async host(input: { instanceId: string; world?: string; nodeId: number; localPort: number; mode: 'auto' | 'manual'; tunnelId?: number }, original: JobContext) {
    if (!['idle', 'error'].includes(this.store.state.room.state)) throw new Error('请先关闭当前房间');
    if (!this.store.state.social.user || !this.store.state.social.connected) throw new Error('请先连接好友服务并登录启源账号');
    const instance = this.store.instance(input.instanceId);
    if (!instance.installed) throw new Error('请先完成游戏安装');
    if (input.mode === 'auto' && (instance.loader !== 'fabric' || instance.gameVersion !== '1.21.1')) throw new Error('自动打开世界支持 Fabric 1.21.1；其他版本请使用已开启的局域网世界');
    if (input.mode === 'auto' && this.store.state.running.includes(instance.id)) throw new Error('自动联机需要从启动器启动，请先退出此实例');
    this.controller = new AbortController(); const epoch = ++this.epoch;
    const context: JobContext = { ...original, signal: AbortSignal.any([original.signal, this.controller.signal]) };
    const update = (state: typeof this.store.state.room.state, detail: string) => { if (epoch !== this.epoch) return; this.store.state.room = { ...this.store.state.room, state, detail, instanceId: instance.id }; this.store.changed(); };
    try {
      update('preparing', '准备世界与联机组件');
      if (input.mode === 'auto') {
        if (!input.world) throw new Error('请选择已有存档。首次使用请先启动游戏创建世界，或导入存档');
        leafSchema.parse(input.world);
        if (await tcpAvailable(input.localPort)) throw new Error('本地端口已被占用，请更换端口');
        const bridge = path.join(this.bundled, 'qinglan-world-bridge-1.21.1.jar');
        if (!(await exists(bridge))) throw new Error('缺少联机桥接模组，请重新安装完整的启动器发行包');
        await this.mods.install(instance, 'fabric-api', 'mod', context);
        await fs.copyFile(bridge, path.join(this.store.instanceDir(instance.id), 'mods', 'qinglan-world-bridge-1.21.1.jar'));
        await this.minecraft.launch(instance.id, context, { world: input.world, lanPort: input.localPort });
        update('waiting-world', '正在打开世界并自动开放局域网');
        for (let i = 0; i < 180; i++) {
          context.signal.throwIfAborted(); if (this.minecraft.lanReady(instance.id) && await tcpAvailable(input.localPort)) break;
          if (!this.store.state.running.includes(instance.id)) throw new Error('游戏已退出，请查看运行日志');
          if (i === 179) throw new Error('等待世界开放超时，请检查游戏画面或版本兼容性');
          context.update('等待游戏世界加载', 0.45); await new Promise(resolve => setTimeout(resolve, 1000));
        }
      } else if (!(await tcpAvailable(input.localPort))) throw new Error('本地局域网端口没有响应，请先在游戏中打开对局域网开放');
      context.signal.throwIfAborted(); update('connecting', '正在配置樱花隧道');
      const remote = await this.sakura.prepare(instance.id, input.nodeId, input.localPort, input.tunnelId);
      this.store.state.room.tunnelId = remote.tunnelId;
      await this.sakura.start(remote.tunnelId, context);
      context.signal.throwIfAborted();
      const actual=instance.loader==='fabric'?await modFiles(this.store.instanceDir(instance.id),await this.ignoredMods()):[];
      const local=instance.loader==='fabric'&&actual.length>0&&needsLocalEnvironment(instance,actual);
      const mods = local?[]:instance.resources.filter(r => instance.loader==='fabric'&&r.kind === 'mod' && r.enabled&&r.source!=='local').map(r => ({ projectId: r.projectId, versionId: r.versionId }));
      const descriptor: Invite = { schema: local?2:1, name: input.world || instance.name, host: remote.host, port: remote.port, gameVersion: instance.gameVersion, loader: instance.loader, loaderVersion: instance.loaderVersion, expiresAt: Date.now() + 86400000, mods,...(local&&actual.length?{localMods:actual}:{}) };
      await this.social.publish(descriptor);
      context.signal.throwIfAborted();
      this.store.state.room = { state: 'ready', detail: local?'世界已开放，好友可选择相同模组的本地实例并校验加入':'好友现在可以看到并加入你的世界', instanceId: instance.id, tunnelId: remote.tunnelId, address: `${remote.host}:${remote.port}` };
      this.store.changed();
      this.monitor = setInterval(() => { void tcpAvailable(input.localPort).then(open => { if (!open && epoch === this.epoch) void this.stop(); }); }, 4000);
      context.update('世界已向好友开放', 1);
    } catch (error) {
      await this.stop();
      this.store.state.room = { state: 'error', detail: error instanceof Error ? error.message : '房间创建失败' }; this.store.changed(); throw error;
    }
  }
  async stop() {
    ++this.epoch; this.controller?.abort(); this.controller = undefined;
    if (this.monitor) clearInterval(this.monitor); this.monitor = undefined;
    this.sakura.stop(); await this.social.unpublish(); this.store.state.room = { state: 'idle', detail: '' }; this.store.changed();
  }
  private async ignoredMods(){const bridge=path.join(this.bundled,'qinglan-world-bridge-1.21.1.jar');return await exists(bridge)?[await hashFile(bridge,'sha512')]:[];}
  async checkLocal(descriptor:Invite,instanceId:string):Promise<ModCheck>{
    const instance=this.store.instance(instanceId);
    if(!versionCompatible(descriptor,instance))return {compatible:false,missing:[],extra:[],reason:'请选择已安装、游戏版本与Fabric加载器版本相同的实例'};
    if(!descriptor.localMods)return {compatible:false,missing:[],extra:[],reason:'好友房间未提供本地模组校验清单'};
    return compareMods(descriptor.localMods,await modFiles(this.store.instanceDir(instanceId),await this.ignoredMods()));
  }
  async join(descriptor: Invite, context: JobContext,localInstanceId?:string) {
    if (descriptor.expiresAt < Date.now()) throw new Error('好友的世界已过期，请刷新');
    if(descriptor.schema===2){
      if(!localInstanceId)throw new Error('请选择已有的本地游戏实例，校验模组后加入好友世界');
      if(this.store.state.running.includes(localInstanceId))throw new Error('请先退出选中的游戏实例');
      const check=await this.checkLocal(descriptor,localInstanceId);
      if(!check.compatible)throw new Error(check.reason||`模组不一致：缺少或版本不同 ${check.missing.length} 项，多出 ${check.extra.length} 项。请按校验清单准备相同文件后重试`);
      context.signal.throwIfAborted();this.store.state.selectedId=localInstanceId;await this.store.save();
      await this.minecraft.launch(localInstanceId,context,{address:`${descriptor.host}:${descriptor.port}`});return;
    }
    // Use a separate instance so joining cannot replace the player's own mod setup.
    const fingerprint = (await import('node:crypto')).createHash('sha256').update(JSON.stringify({ gameVersion: descriptor.gameVersion, loader: descriptor.loader, loaderVersion: descriptor.loaderVersion, mods: [...descriptor.mods].sort((a, b) => a.projectId.localeCompare(b.projectId)) })).digest('hex').slice(0, 24);
    const id = `friend-${fingerprint}`;
    let instance = this.store.state.instances.find(item => item.id === id);
    if (!instance) { instance = { ...this.minecraft.newInstance(`好友世界 · ${descriptor.gameVersion}`, descriptor.gameVersion, descriptor.loader, descriptor.loaderVersion), id }; this.store.state.instances.push(instance); await this.store.save(); }
    if (this.store.state.running.includes(id)) throw new Error('此好友游戏环境已在运行，请先退出该实例');
    if (!instance.installed) await this.minecraft.install(instance, context);
    for (const mod of descriptor.mods) if (!instance.resources.some(r => r.projectId === mod.projectId && r.versionId === mod.versionId && r.enabled)) await this.mods.install(instance, mod.projectId, 'mod', context, mod.versionId);
    this.store.state.selectedId = id; await this.store.save();
    await this.minecraft.launch(id, context, { address: `${descriptor.host}:${descriptor.port}` });
  }
}
