import fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import AdmZip from 'adm-zip';
import { parse as parseToml } from 'smol-toml';
import { identifier, leafSchema, under } from './safety';
import { parallel } from './network';
import { readWorld } from './world-info';
import type { DetectedLoader, LocalProfile, LocalResource, LocalScan, ResourceKind } from '../../shared/types';

export const CONTENT_DIRS = ['mods', 'saves', 'resourcepacks', 'shaderpacks', 'config', 'defaultconfigs', 'kubejs', 'scripts'] as const;
export const CONTENT_FILES = ['options.txt', 'optionsof.txt', 'optionsshaders.txt', 'servers.dat'] as const;
const METADATA_LIMIT = 512 * 1024;
const VERSION_PATTERN = /^(?:\d{1,2}\.\d+(?:\.\d+)?(?:-(?:pre|rc|snapshot)-?\d+)?|\d{2}w\d{2}[a-z])$/;
const modernVersion = (version: string) => Number(/^1\.(\d+)/.exec(version)?.[1] ?? Infinity) >= 13;

export async function localPath(root: string, ...parts: string[]) {
  const target = under(root, ...parts);
  try {
    const stat = await fs.lstat(target);
    if (stat.isSymbolicLink()) return undefined;
    const real = await fs.realpath(target);
    under(root, path.relative(root, real));
    return { path: target, stat };
  } catch { return undefined; }
}
async function directories(root: string) {
  try { return (await fs.readdir(root, { withFileTypes: true })).filter(entry => entry.isDirectory() && !entry.isSymbolicLink()).sort((a, b) => a.name.localeCompare(b.name)); }
  catch { return []; }
}
async function readSmallJson(root: string, ...parts: string[]): Promise<Record<string, unknown> | undefined> {
  const item = await localPath(root, ...parts);
  if (!item || !item.stat.isFile() || item.stat.size > 2 * 1024 ** 2) return undefined;
  try { const value: unknown = JSON.parse(await fs.readFile(item.path, 'utf8')); return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : undefined; } catch { return undefined; }
}
const text = (value: unknown) => typeof value === 'string' ? value.slice(0, 500) : undefined;
const description = (value: unknown): string | undefined => typeof value === 'string' ? value.slice(0, 500) : Array.isArray(value) ? value.map(description).filter(Boolean).join(' ').slice(0, 500) : value && typeof value === 'object' ? description((value as { text?: unknown }).text) : undefined;
function archiveText(zip: AdmZip, name: string) {
  const entry = zip.getEntry(name);
  if (!entry || entry.isDirectory || entry.header.size > METADATA_LIMIT || entry.header.compressedSize > METADATA_LIMIT) return undefined;
  const buffer = entry.getData(); if (buffer.length > METADATA_LIMIT) throw new Error('元数据体积超限'); return buffer.toString('utf8');
}
export async function sniffResource(root: string, folder: string, filename: string, kind: ResourceKind): Promise<LocalResource> {
  const item = await localPath(root, folder, filename);
  const enabled = !/\.(disabled|disable|old)$/i.test(filename);
  const base = filename.replace(/\.(disabled|disable|old)$/i, '').replace(/\.(jar|zip)$/i, '');
  const result: LocalResource = { filename, name: base, kind, enabled, size: item?.stat.size || 0, loaders: [] };
  if (item?.stat.isDirectory() && kind !== 'mod') {
    result.directory = true; result.size = 0;
    const metadata = await readSmallJson(root, folder, filename, 'pack.mcmeta');
    const pack = metadata?.pack as { description?: unknown; pack_format?: unknown } | undefined;
    result.description = description(pack?.description); if (typeof pack?.pack_format === 'number') result.packFormat = pack.pack_format;
    return result;
  }
  if (!item || !item.stat.isFile()) { result.warning = '文件已移动或不可访问'; return result; }
  if (item.stat.size > 256 * 1024 ** 2) { result.warning = '文件较大，未展开内部元数据'; return result; }
  try {
    if (item.stat.isDirectory()) return result;
    const zip = new AdmZip(item.path);
    if (kind !== 'mod') {
      const metadata = archiveText(zip, 'pack.mcmeta');
      if (metadata) { const pack = JSON.parse(metadata).pack; result.description = description(pack?.description); if (Number.isSafeInteger(pack?.pack_format)) result.packFormat = pack.pack_format; }
      return result;
    }
    const fabric = archiveText(zip, 'fabric.mod.json');
    const quilt = archiveText(zip, 'quilt.mod.json');
    const forge = archiveText(zip, 'META-INF/mods.toml');
    const neo = archiveText(zip, 'META-INF/neoforge.mods.toml');
    if (fabric) { const data = JSON.parse(fabric); result.name = text(data.name) || text(data.id) || base; result.modId = text(data.id); result.version = text(data.version); result.description = description(data.description); result.loaders.push('fabric'); }
    if (quilt) { const data = JSON.parse(quilt).quilt_loader; if (!fabric) { result.name = text(data?.metadata?.name) || text(data?.id) || base; result.modId = text(data?.id); result.version = text(data?.version); } result.loaders.push('quilt'); }
    for (const [metadata, loader] of [[forge, 'forge'], [neo, 'neoforge']] as const) if (metadata) {
      const data = parseToml(metadata) as { mods?: { modId?: string; displayName?: string; version?: string; description?: string }[] };
      const mod = data.mods?.[0];
      if (!fabric && !quilt) { result.name = text(mod?.displayName) || text(mod?.modId) || base; result.modId = text(mod?.modId); result.version = text(mod?.version); result.description = description(mod?.description); }
      result.loaders.push(loader);
    }
    if (result.version?.includes('${')) { const manifest = archiveText(zip, 'META-INF/MANIFEST.MF'); result.version = manifest?.match(/^Implementation-Version:\s*(.+)$/m)?.[1]?.trim(); }
    if (!result.loaders.length) {
      const legacy = archiveText(zip, 'mcmod.info');
      if (legacy) { const data = JSON.parse(legacy); const mod = Array.isArray(data) ? data[0] : data.modList?.[0]; result.name = text(mod?.name) || base; result.modId = text(mod?.modid); result.version = text(mod?.version); result.loaders.push('forge'); }
      else result.warning = '未发现常见模组元数据，保留文件名';
    }
  } catch { result.warning = '元数据损坏或格式不受支持，文件仍可查看'; }
  return result;
}
export async function sniffContents(gameDir: string): Promise<Pick<LocalProfile, 'resources' | 'worlds' | 'warnings'>> {
  const resources: LocalResource[] = []; const worlds: LocalProfile['worlds'] = []; const warnings: string[] = [];
  for (const [folder, kind] of [['mods', 'mod'], ['shaderpacks', 'shader'], ['resourcepacks', 'resourcepack']] as const) {
    const directory = await localPath(gameDir, folder);
    if (!directory?.stat.isDirectory()) {
      try { if ((await fs.lstat(under(gameDir, folder))).isSymbolicLink()) warnings.push(`已跳过链接目录 ${folder}，不会读取或复制链接指向的内容`); } catch { /* absent */ }
      continue;
    }
    const entries = [];
    for (const entry of await fs.readdir(directory.path, { withFileTypes: true })) {
      if (entry.isSymbolicLink()) continue;
      if (entry.isFile() && (kind === 'mod' ? /\.jar(?:\.(?:disabled|disable|old))?$/i : /\.zip(?:\.(?:disabled|disable|old))?$/i).test(entry.name)) entries.push(entry);
      else if (entry.isDirectory() && kind !== 'mod' && (await localPath(gameDir, folder, entry.name, 'pack.mcmeta') || kind === 'shader' && await localPath(gameDir, folder, entry.name, 'shaders'))) entries.push(entry);
    }
    entries.sort((a, b) => a.name.localeCompare(b.name));
    if (entries.length > 1500) warnings.push(`${folder} 仅展示前 1500 项，导入时仍复制选定目录的文件`);
    const inspected: LocalResource[] = [];
    await parallel(entries.slice(0, 1500), 3, async (entry, index) => { inspected[index] = await sniffResource(gameDir, folder, entry.name, kind); });
    resources.push(...inspected);
  }
  const saveRoot = await localPath(gameDir, 'saves');
  if (saveRoot?.stat.isDirectory()) for (const entry of (await directories(saveRoot.path)).slice(0, 1000)) {
    const file = await localPath(gameDir, 'saves', entry.name, 'level.dat');
    if (file?.stat.isFile()) worlds.push(await readWorld(file.path, entry.name));
  }
  worlds.sort((a, b) => (b.lastPlayed || 0) - (a.lastPlayed || 0));
  return { resources, worlds, warnings };
}
function loaderInfo(metadata: Record<string, unknown>[]): { loader: DetectedLoader; version?: string } {
  const libraries = metadata.flatMap(data => Array.isArray(data.libraries) ? data.libraries : []).filter((value): value is { name: string } => !!value && typeof value.name === 'string');
  for (const [prefix, loader] of [['net.neoforged:neoforge:', 'neoforge'], ['net.minecraftforge:forge:', 'forge'], ['org.quiltmc:quilt-loader:', 'quilt'], ['net.fabricmc:fabric-loader:', 'fabric']] as const) {
    const match = libraries.find(item => item.name.startsWith(prefix)); if (match) return { loader, version: match.name.slice(prefix.length).split(':')[0] };
  }
  const classes = metadata.map(data => text(data.mainClass) || '').join(' ');
  if (/fabricmc|KnotClient/i.test(classes)) return { loader: 'fabric' };
  if (/quiltmc/i.test(classes)) return { loader: 'quilt' };
  if (/modlauncher|forge/i.test(classes)) return { loader: 'forge' };
  return { loader: /net\.minecraft\.(client\.main\.Main|launchwrapper\.Launch)/.test(classes) ? 'vanilla' : 'unknown' };
}
export async function scanLocalFolder(selected: string): Promise<LocalScan> {
  const selectedPath = await fs.realpath(selected); if (!(await fs.stat(selectedPath)).isDirectory()) throw new Error('请选择游戏文件夹');
  const report: LocalScan = { id: randomUUID(), selectedPath, scannedAt: new Date().toISOString(), profiles: [], warnings: [] };
  const roots = new Set<string>(); const directProfiles: { root: string; directory: string }[] = [];
  const addRoot = async (directory: string) => { try { const real = await fs.realpath(directory); if ((await fs.lstat(directory)).isSymbolicLink()) return; roots.add(real); } catch { /* absent */ } };
  if (path.basename(path.dirname(selectedPath)).toLowerCase() === 'versions') directProfiles.push({ root: path.dirname(path.dirname(selectedPath)), directory: selectedPath });
  else if (path.basename(selectedPath).toLowerCase() === 'versions') await addRoot(path.dirname(selectedPath));
  else {
    await addRoot(selectedPath);
    const minecraft = await localPath(selectedPath, '.minecraft'); if (minecraft?.stat.isDirectory()) await addRoot(minecraft.path);
    const instances = await localPath(selectedPath, 'instances');
    const container = instances?.stat.isDirectory() ? instances.path : selectedPath;
    for (const entry of (await directories(container)).slice(0, 100)) {
      if (['versions', 'libraries', 'assets', 'mods', 'saves', 'resourcepacks', 'shaderpacks', 'config'].includes(entry.name)) continue;
      const wrapped = await localPath(container, entry.name, '.minecraft'); if (wrapped?.stat.isDirectory()) await addRoot(wrapped.path);
      else if (instances && await localPath(container, entry.name, 'versions')) await addRoot(under(container, entry.name));
    }
  }
  const candidates = [...directProfiles];
  for (const root of roots) {
    if ((await localPath(root, '.minecraft'))?.stat.isDirectory()) continue;
    const versions = await localPath(root, 'versions');
    if (versions?.stat.isDirectory()) for (const entry of (await directories(versions.path)).slice(0, 128)) candidates.push({ root, directory: under(versions.path, entry.name) });
    else {
      const mmc = await readSmallJson(root, 'mmc-pack.json') || await readSmallJson(path.dirname(root), 'mmc-pack.json');
      const components = Array.isArray(mmc?.components) ? mmc.components as Record<string, unknown>[] : [];
      if (components.length) {
        const minecraft = components.find(component => component.uid === 'net.minecraft');
        const loaderComponent = components.find(component => ['net.fabricmc.fabric-loader', 'net.minecraftforge', 'net.neoforged', 'org.quiltmc.quilt-loader'].includes(String(component.uid)));
        const loader: DetectedLoader = loaderComponent ? String(loaderComponent.uid).includes('fabric') ? 'fabric' : String(loaderComponent.uid).includes('neoforged') ? 'neoforge' : String(loaderComponent.uid).includes('quilt') ? 'quilt' : 'forge' : 'vanilla';
        const gameVersion = text(minecraft?.version); const contents = await sniffContents(root);
        const supported = !!gameVersion && modernVersion(gameVersion) && (loader === 'fabric' || loader === 'vanilla');
        report.profiles.push({ id: randomUUID(), name: path.basename(path.dirname(root)), gameVersion, loader, loaderVersion: text(loaderComponent?.version), gameDir: root, cacheRoot: root, isolated: true, ...contents, canImport: supported, importReason: supported ? undefined : '此加载器暂仅支持识别和查看' });
      } else if (await localPath(root, 'mods') || await localPath(root, 'saves')) {
        const contents = await sniffContents(root);
        report.profiles.push({ id: randomUUID(), name: path.basename(root), loader: 'unknown', gameDir: root, cacheRoot: root, isolated: true, ...contents, canImport: false, importReason: '发现游戏内容，但缺少可确认版本的启动配置' });
      }
    }
  }
  const contentCache = new Map<string, Awaited<ReturnType<typeof sniffContents>>>();
  for (const { root, directory } of candidates.slice(0, 128)) {
    const files = (await fs.readdir(directory, { withFileTypes: true })).filter(entry => entry.isFile() && !entry.isSymbolicLink() && entry.name.endsWith('.json') && !/account|credential|token|session|launcher_profiles/i.test(entry.name));
    let metadata: Record<string, unknown> | undefined;
    const usual = `${path.basename(directory)}.json`;
    for (const file of [...files.filter(file => file.name === usual), ...files.filter(file => file.name !== usual)].slice(0, 16)) { const data = await readSmallJson(root, 'versions', path.basename(directory), file.name); if (data && (data.mainClass || data.inheritsFrom || data.downloads)) { metadata = data; break; } }
    if (!metadata) continue;
    const warnings: string[] = []; const chain = [metadata]; const visited = new Set<string>();
    let parent = text(metadata.inheritsFrom);
    for (let depth = 0; parent && depth < 12; depth++) {
      if (visited.has(parent)) { warnings.push('版本继承循环，已停止追踪'); break; } visited.add(parent);
      if (!leafSchema.safeParse(parent).success) { warnings.push('版本继承路径无效'); break; }
      const data = await readSmallJson(root, 'versions', parent, `${parent}.json`);
      if (!data) { warnings.push(`缺少基础版本配置 ${parent}，导入时将从官方补齐`); break; }
      chain.push(data); parent = text(data.inheritsFrom);
    }
    let gameVersion = chain.slice().reverse().flatMap(data => [text(data.clientVersion), text(data.jar), text(data.id)]).find(id => !!id && VERSION_PATTERN.test(id)) || [...visited].reverse().find(id => VERSION_PATTERN.test(id));
    if (!gameVersion) {
      // Some launchers flatten inheritance and rename the profile. Read the client's
      // embedded version.json instead of mistaking "1.21.1-Fabric" for an official ID.
      const client = await localPath(root, 'versions', path.basename(directory), `${path.basename(directory)}.jar`);
      if (client?.stat.isFile() && client.stat.size <= 256 * 1024 ** 2) {
        try { const metadata = archiveText(new AdmZip(client.path), 'version.json'); const id = metadata && text(JSON.parse(metadata).id); if (id && VERSION_PATTERN.test(id)) gameVersion = id; }
        catch { warnings.push('无法从客户端读取内置版本信息'); }
      }
    }
    const detected = loaderInfo(chain);
    let gameDir = root;
    const nested = await localPath(root, 'versions', path.basename(directory), '.minecraft');
    if (nested?.stat.isDirectory()) gameDir = nested.path;
    else if ((await Promise.all([...CONTENT_DIRS, 'options.txt'].map(name => localPath(directory, name)))).some(Boolean)) gameDir = directory;
    let contents = contentCache.get(gameDir); if (!contents) { contents = await sniffContents(gameDir); contentCache.set(gameDir, contents); }
    const supported = !!gameVersion && modernVersion(gameVersion) && (detected.loader === 'fabric' || detected.loader === 'vanilla') && identifier.safeParse(gameVersion).success;
    report.profiles.push({ id: randomUUID(), name: text(metadata.id) || path.basename(directory), gameVersion, loader: detected.loader, loaderVersion: detected.version, gameDir, cacheRoot: root, versionDir: directory, isolated: gameDir !== root, resources: contents.resources, worlds: contents.worlds, warnings: [...warnings, ...contents.warnings], canImport: supported, importReason: supported ? undefined : !gameVersion ? '无法确认 Minecraft 基础版本' : !modernVersion(gameVersion) ? '此旧版本暂仅支持识别；当前导入启动支持 1.13 及以上版本' : '此加载器暂仅支持识别和查看，不能直接导入启动' });
  }
  for (const root of new Set([...roots, ...directProfiles.map(profile => profile.directory)])) {
    if (report.profiles.some(profile => profile.cacheRoot === root || profile.gameDir === root) || (await localPath(root, '.minecraft'))?.stat.isDirectory()) continue;
    if (await localPath(root, 'mods') || await localPath(root, 'saves')) {
      const contents = await sniffContents(root);
      report.profiles.push({ id: randomUUID(), name: path.basename(root), loader: 'unknown', gameDir: root, cacheRoot: root, isolated: true, ...contents, canImport: false, importReason: '发现游戏内容，但缺少可确认版本的启动配置' });
    }
  }
  if (!report.profiles.length) report.warnings.push('没有找到游戏版本、模组或存档。可选择 .minecraft、versions、具体版本目录或整合包实例目录。');
  return report;
}
