import type { Store } from './store';
import type { Friend, Invite, SocialState } from '../../shared/types';
import { inviteSchema } from './invite';
export function friendsUrl(value: string) {
  const url = new URL(value);
  const local = ['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname);
  if ((url.protocol !== 'https:' && !(local && url.protocol === 'http:')) || url.username || url.password || url.search || url.hash || url.pathname !== '/') throw new Error('好友服务请填写 HTTPS 地址，本机调试可使用 http://127.0.0.1:4589');
  return url.origin;
}
export class Social {
  private timer?: NodeJS.Timeout; private busy = false; private generation = 0;
  private room?: Invite;
  constructor(private store: Store) {}
  private token() { const stored = this.store.secret('friends'); if (!stored) return undefined; const value = JSON.parse(stored) as { server: string; token: string }; return value.server === friendsUrl(this.store.state.settings.friendsServer) ? value.token : undefined; }
  async api<T>(route: string, method = 'GET', body?: unknown, token = this.token()): Promise<T> {
    const response = await fetch(`${friendsUrl(this.store.state.settings.friendsServer)}${route}`, { method, redirect: 'error', signal: AbortSignal.timeout(12000), headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) }, body: body === undefined ? undefined : JSON.stringify(body) });
    const value = await response.json() as T & { error?: string };
    if (!response.ok) {
      if (response.status === 401 && route !== '/v1/login') { await this.store.setSecret('friends'); this.store.state.social = { connected: false, friends: [], error: '登录已过期，请重新登录' }; this.store.changed(); }
      throw new Error(value.error || `好友服务返回 ${response.status}`);
    }
    return value;
  }
  start() { this.stop(); void this.refresh(); this.timer = setInterval(() => void this.refresh(), 15000); }
  stop() { if (this.timer) clearInterval(this.timer); this.timer = undefined; }
  async pause() { this.stop(); ++this.generation; while(this.busy) await new Promise(resolve=>setTimeout(resolve,25)); }
  async refresh() {
    if (this.busy) return; this.busy = true; const generation = this.generation;
    try {
      if (!this.token()) return;
      const value = await this.api<{ user: SocialState['user']; friends: Friend[] }>('/v1/presence', 'POST', {});
      if (generation !== this.generation) return;
      this.store.state.social = { user: value.user, friends: value.friends, connected: true, updatedAt: Date.now() };
      if (this.room && this.store.state.room.state === 'ready') await this.api('/v1/room', 'PUT', this.room);
    } catch (error) { if (generation === this.generation) { this.store.state.social.connected = false; this.store.state.social.friends = this.store.state.social.friends.map(friend => ({ ...friend, online: false, world: undefined })); this.store.state.social.error = error instanceof Error ? error.message : '好友服务暂时不可用'; } }
    finally { this.busy = false; this.store.changed(); }
  }
  async login(input: { username: string; password: string; nickname?: string; register: boolean }) {
    ++this.generation;
    const value = await this.api<{ token: string; user: SocialState['user']; friends: Friend[] }>(input.register ? '/v1/register' : '/v1/login', 'POST', { username: input.username, password: input.password, nickname: input.nickname }, '');
    await this.store.setSecret('friends', JSON.stringify({ server: friendsUrl(this.store.state.settings.friendsServer), token: value.token }));
    this.store.state.social = { user: value.user, friends: value.friends, connected: true, updatedAt: Date.now() }; this.store.changed();
  }
  async logout() { ++this.generation; if (this.token()) await this.api('/v1/logout', 'POST', {}).catch(() => {}); await this.store.setSecret('friends'); this.room = undefined; this.store.state.social = { connected: false, friends: [] }; this.store.changed(); }
  async add(username: string) { await this.api('/v1/friends', 'POST', { username }); await this.refresh(); }
  async respond(id: string, accept: boolean) { await this.api(`/v1/friends/${id}`, 'PATCH', { accept }); await this.refresh(); }
  async remove(id: string) { await this.api(`/v1/friends/${id}`, 'DELETE'); await this.refresh(); }
  async publish(room: Invite) { if(room.schema===2){const health=await this.api<{roomSchemas?:number[]}>('/health');if(!health.roomSchemas?.includes(2))throw new Error('本地模组联机需要更新好友服务端至 OLS 0.4.0 或更高版本');} await this.api('/v1/room', 'PUT', room); this.room = room; }
  async unpublish() { this.room = undefined; if (this.token()) await this.api('/v1/room', 'DELETE').catch(() => {}); }
  async getRoom(id: string) { return inviteSchema.parse(await this.api<Invite>(`/v1/rooms/${id}`)); }
  async shutdown() { ++this.generation; this.stop(); this.room = undefined; if (this.token()) await this.api('/v1/disconnect', 'POST', {}).catch(() => {}); }
}
