import { randomUUID } from 'node:crypto';
import type { Job } from '../../shared/types';
import type { Store } from './store';
import { safeMessage } from './safety';
export interface JobContext { signal: AbortSignal; update: (detail: string, progress?: number, bytes?: number, totalBytes?: number) => void; beginCommit?: () => void }
type Work = (context: JobContext) => Promise<void>;
export class Jobs {
  private work = new Map<string, { controller: AbortController; action: Work; commitStarted?: boolean }>();
  private queue: string[] = []; private active = false;
  constructor(private store: Store) {}
  add(title: string, action: Work) {
    const id = randomUUID();
    const job: Job = { id, title, status: 'queued', detail: '等待开始', progress: 0, bytes: 0, totalBytes: 0, createdAt: new Date().toISOString() };
    this.store.state.jobs.unshift(job); this.store.state.jobs = this.store.state.jobs.slice(0, 100);
    this.work.set(id, { controller: new AbortController(), action }); this.queue.push(id);
    this.store.changed(); void this.drain(); return id;
  }
  cancel(id: string) {
    const job = this.store.state.jobs.find(item => item.id === id);
    if (!job || !['running', 'queued'].includes(job.status)) return;
    if (this.work.get(id)?.commitStarted) return;
    this.work.get(id)?.controller.abort(new Error('任务已取消'));
    if (job.status === 'queued') { job.status = 'cancelled'; job.detail = '已取消'; this.queue = this.queue.filter(key => key !== id); }
    this.store.changed();
  }
  cancelAll() { for (const id of this.work.keys()) this.cancel(id); }
  retry(id: string) {
    const action = this.work.get(id)?.action; const job = this.store.state.jobs.find(item => item.id === id);
    if (!action || !job || !['failed', 'cancelled'].includes(job.status)) throw new Error('此任务不能重试');
    return this.add(job.title, action);
  }
  private async drain() {
    if (this.active) return; this.active = true;
    try {
      while (this.queue.length) {
        const id = this.queue.shift()!; const work = this.work.get(id)!;
        const job = this.store.state.jobs.find(item => item.id === id); if (!job) continue;
        if (work.controller.signal.aborted) continue;
        job.status = 'running'; this.store.changed();
        try {
          await work.action({ signal: work.controller.signal, beginCommit:()=>{work.controller.signal.throwIfAborted();work.commitStarted=true;}, update: (detail, progress, bytes, totalBytes) => {
            job.detail = detail; if (progress !== undefined) job.progress = Math.max(0, Math.min(1, progress));
            if (bytes !== undefined) job.bytes = bytes; if (totalBytes !== undefined) job.totalBytes = totalBytes;
            this.store.changed();
          } });
          work.controller.signal.throwIfAborted(); job.status = 'done'; job.progress = 1; job.detail = '已完成';
        } catch (error) {
          job.status = work.controller.signal.aborted ? 'cancelled' : 'failed'; job.error = safeMessage(error); job.detail = job.error;
          this.store.log(`${job.title}：${job.error}`);
        }
        this.store.changed();
      }
    } finally { this.active = false; }
  }
}
