import fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID, createHash } from 'node:crypto';
import { CONTENT_DIRS, CONTENT_FILES, localPath, sniffContents } from './local-scan';
import { exists, hashFile } from './files';
import { under, leafSchema } from './safety';
import type { Download } from './network';
import type { JobContext } from './jobs';
import type { Instance, LocalProfile, Resource } from '../../shared/types';

export interface LocalSeed { cacheRoot: string; versionDir?: string }
export async function seedLocalDownload(item: Download, destinationRoot: string, seed: LocalSeed, signal: AbortSignal): Promise<boolean> {
  if (await exists(item.file) || !item.hash) return false;
  const relative = path.relative(destinationRoot, item.file);
  const parts = relative.split(path.sep);
  if (!['versions', 'libraries', 'assets', 'logging'].includes(parts[0])) return false;
  const options = [{ root: seed.cacheRoot, parts }];
  if (parts[0] === 'versions' && parts.at(-1)?.endsWith('.jar') && seed.versionDir) options.push({ root: seed.versionDir, parts: [`${path.basename(seed.versionDir)}.jar`] });
  for (const option of options) {
    signal.throwIfAborted(); const source = await localPath(option.root, ...option.parts);
    if (!source?.stat.isFile() || (item.size && source.stat.size !== item.size)) continue;
    if (await hashFile(source.path, item.algorithm || 'sha1') !== item.hash.toLowerCase()) continue;
    signal.throwIfAborted(); await fs.mkdir(path.dirname(item.file), { recursive: true });
    const temp = `${item.file}.${randomUUID()}.seed`;
    try { await fs.copyFile(source.path, temp); signal.throwIfAborted(); await fs.rename(temp, item.file); return true; }
    finally { await fs.rm(temp, { force: true }); }
  }
  return false;
}

/** Copies only the selected game's content. No accounts, launch scripts or launcher settings. */
export async function copyLocalContent(profile: LocalProfile, destination: string, context: JobContext): Promise<Resource[]> {
  const root = await fs.realpath(profile.gameDir);
  const target = path.resolve(destination);
  const relativeTarget = path.relative(root, target);
  if (!relativeTarget || relativeTarget !== '..' && !relativeTarget.startsWith(`..${path.sep}`) && !path.isAbsolute(relativeTarget)) throw new Error('导入目标不能位于原游戏目录中');
  const plan: { source: string; relative: string; size: number }[] = [];
  let total = 0; let visited = 0;
  const walk = async (relative: string, depth: number): Promise<void> => {
    context.signal.throwIfAborted(); if (depth > 40 || ++visited > 200000) throw new Error('游戏内容超出导入范围，请拆分大型目录后重试');
    const candidate = under(root, relative); const stat = await fs.lstat(candidate);
    if (stat.isSymbolicLink()) throw new Error(`导入内容包含链接，请先移除链接：${relative}`);
    const item = await localPath(root, relative); if (!item) throw new Error(`文件已移动或不能访问：${relative}`);
    if (stat.isDirectory()) { for (const entry of await fs.readdir(candidate)) { leafSchema.parse(entry); await walk(path.join(relative, entry), depth + 1); } }
    else if (stat.isFile() && path.basename(relative) !== 'session.lock') { plan.push({ source: candidate, relative, size: stat.size }); total += stat.size; }
  };
  context.update('统计需要复制的模组、配置和存档', 0.01);
  for (const name of [...CONTENT_DIRS, ...CONTENT_FILES]) {
    try { if ((await fs.lstat(under(root, name))).isSymbolicLink()) throw new Error(`导入内容包含链接，请先移除链接：${name}`); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue; throw error; }
    await walk(name, 0);
  }
  await fs.mkdir(target, { recursive: true });
  const space = await fs.statfs(target); if (space.bavail * space.bsize < total + 64 * 1024 ** 2) throw new Error('OLS 数据目录磁盘空间不足，尚未复制游戏内容');
  let copied = 0; let count = 0;
  for (const file of plan) {
    context.signal.throwIfAborted();
    const current = await localPath(root, file.relative); if (!current?.stat.isFile()) throw new Error(`复制前文件已移动：${file.relative}`);
    const output = under(target, file.relative); await fs.mkdir(path.dirname(output), { recursive: true });
    const temp = `${output}.${randomUUID()}.import`;
    try { await fs.copyFile(current.path, temp); context.signal.throwIfAborted(); await fs.rename(temp, output); }
    finally { await fs.rm(temp, { force: true }); }
    copied += file.size; count++;
    context.update(`复制 ${count} / ${plan.length} · ${file.relative}`, 0.03 + count / Math.max(1, plan.length) * 0.87, copied, total);
  }
  // Re-read the copied metadata rather than persisting a possibly stale scan snapshot.
  const contents = await sniffContents(target);
  const resources: Resource[] = [];
  const directoryHash = async (directory: string) => {
    const hash = createHash('sha512');
    const visit = async (relative: string): Promise<void> => {
      context.signal.throwIfAborted();
      for (const entry of (await fs.readdir(under(directory, relative), { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
        if (entry.isSymbolicLink()) throw new Error('复制目录出现链接，已停止导入');
        const child = path.join(relative, entry.name);
        if (entry.isDirectory()) await visit(child);
        else if (entry.isFile()) hash.update(`${child}\0${await hashFile(under(directory, child), 'sha512')}\0`);
      }
    };
    await visit(''); return hash.digest('hex');
  };
  for (const item of contents.resources) {
    context.signal.throwIfAborted();
    const dir = { mod: 'mods', shader: 'shaderpacks', resourcepack: 'resourcepacks' }[item.kind];
    const hash = item.directory ? await directoryHash(under(target, dir, item.filename)) : await hashFile(under(target, dir, item.filename), 'sha512');
    const filename = item.enabled ? item.filename : item.filename.replace(/\.(disabled|disable|old)$/i, '');
    // Normalize launcher-specific disabled extensions in the destination only.
    if (!item.enabled && item.filename !== `${filename}.disabled`) {
      if (await exists(under(target, dir, `${filename}.disabled`))) throw new Error(`有多个同名停用资源，请在原目录整理后重新导入：${filename}`);
      await fs.rename(under(target, dir, item.filename), under(target, dir, `${filename}.disabled`));
    }
    resources.push({ projectId: `local-${createHash('sha256').update(`${dir}/${filename}`).digest('hex').slice(0, 24)}`, versionId: `local-${hash.slice(0, 24)}`, name: item.name, filename, kind: item.kind, sha512: hash, enabled: item.enabled, source: 'local', modId: item.modId, displayVersion: item.version, directory: item.directory });
  }
  context.update('本地游戏内容已复制，准备校验运行文件', 1);
  return resources;
}
export function canRepairImported(instance: Instance) {
  if (instance.importState === 'copying' || instance.importState === 'failed') throw new Error('本地内容尚未复制完整，请在下载管理重试原导入任务；重新打开启动器后可重新扫描并导入');
}
