import fs from 'node:fs/promises';
import path from 'node:path';
import { spawn, execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { randomUUID } from 'node:crypto';
import { download, json, parallel, request, type Download } from './network';
import { atomicWrite, exists, extractZip, readJson } from './files';
import { identifier, under, leafSchema } from './safety';
import { seedLocalDownload, type LocalSeed } from './local-import';
