        const loaders = await json<{ loader: { version: string; stable: boolean } }[]>(`https://meta.fabricmc.net/v2/versions/loader/${encodeURIComponent(instance.gameVersion)}`, {}, context.signal);
        const loader = loaders.find(v => v.loader.stable) || loaders[0]; if (!loader) throw new Error('这个 Minecraft 版本暂时没有 Fabric 加载器');
