      const profile = await json<{ id: string; mainClass: string; libraries: Library[]; arguments: { game: Argument[]; jvm: Argument[] } }>(`https://meta.fabricmc.net/v2/versions/loader/${encodeURIComponent(instance.gameVersion)}/${encodeURIComponent(instance.loaderVersion)}/profile/json`, {}, context.signal);
